/**
 * Monograph: a flat, monochrome redesign of the Hermes desktop app.
 *
 * GENERATED by build.mjs from src/. Edit the sources, not the built file.
 *
 * The whole look ships from here as one injected stylesheet, so it is not
 * bound by the skin's 32 KiB customCSS cap. The skin only carries colours and
 * a first-paint veil that this plugin lifts once the stylesheet is in place.
 */
// Namespace import on purpose: a named import of something an older Hermes
// does not export fails the whole module, and with it the stylesheet. Read
// optional pieces off `sdk` and check them first.
import * as sdk from '@hermes/plugin-sdk'
import * as React from 'react'
import { useEffect, useState, useSyncExternalStore } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

const ID = 'monograph'
const VERSION = "__MG_VERSION__"
const CSS = "__MG_CSS__"
// The motion-off kill switch, kept out of CSS (build.mjs); 50-motion.js puts
// it in its own <style id="mg-motion-off"> only while motion is off.
const MOTION_OFF_CSS = "__MG_MOTION_OFF_CSS__"
const DEFAULTS = "__MG_DEFAULTS__"
// [[logo, [needle, …]], …] from src/logos/index.json. First match wins.
const LOGOS = "__MG_LOGOS__"

const STYLE_ID = 'mg-css'

// ── State machines ──────────────────────────────────────────────────────────
// build.mjs puts every file of src/machines/ here and lists them in MACHINES.
// A machine is pure: states by name and one step(state, event, now). The code
// that feeds it events and draws its state (its adapter) lives below, in the
// core or in a module. The contract and the list: docs/state-machines.md.
/* __MG_MACHINES__ */

// ── Settings: build defaults, overlaid by what the user changed in the app ──
let storage = null
let saved = {}
let config = { ...DEFAULTS }
const listeners = new Set()

const getConfig = () => config

const subscribe = listener => {
  listeners.add(listener)

  return () => listeners.delete(listener)
}

// The line an empty chat opens with. A greeting of the user's own may hold
// "{name}"; with no name set, the placeholder goes, and the comma before it.
function greeting(current) {
  const name = String(current.name || '').trim()
  const own = String(current.greeting || '').trim()

  if (own) {
    // A function replacer: a name is text, so `$&`, `$1` and the like in it
    // must not be read as replacement patterns.
    return name ? own.replaceAll('{name}', () => name) : own.replace(/,?\s*\{name\}/g, '')
  }

  return name ? `What are we working on today, ${name}?` : 'What are we working on today?'
}

const toolsShown = current => current.tools !== 'hidden'
// Live reasoning: "live" draws it as a few dim lines while the model works,
// "line" draws none of it while the turn runs (it stays under "Worked for").
const thinkingMode = current => (current.thinking === 'line' ? 'line' : 'live')

function applyConfig(current) {
  const root = document.documentElement

  root.style.setProperty('--mg-greeting', JSON.stringify(greeting(current)))
  root.dataset.mgTools = toolsShown(current) ? 'shown' : 'hidden'
  root.dataset.mgThinking = thinkingMode(current)
  // Stylesheets read these two; anything else in the config is its module's.
  root.dataset.mgMotion = current.motion === 'off' ? 'off' : 'on'
  root.dataset.mgDensity = current.density === 'compact' ? 'compact' : 'comfortable'
}

function setConfig(patch) {
  const before = config

  saved = { ...saved, ...patch }
  config = { ...DEFAULTS, ...saved }
  storage?.set('config', saved)

  // Tool calls shown or hidden changes the height of everything above the
  // reader: keep the first line of text they are reading where it is.
  const hold = toolsShown(before) !== toolsShown(config) ? holdReading() : null

  applyConfig(config)
  hold?.()
  listeners.forEach(listener => listener())
}

// The text a reader scrolled up in a thread is looking at: the first few
// lines of prose (or prompt text) from the top of each visible viewport not
// at the bottom, found by pointing, not by reading every row. Returns the
// function that puts the first of them still drawn back where it was.
function holdReading() {
  const holds = []

  for (const viewport of document.querySelectorAll(VIEWPORT)) {
    const box = viewport.getBoundingClientRect()

    if (box.height < 40 || viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight <= 2) {
      continue
    }

    const x = box.left + box.width / 2
    const nodes = []

    for (let y = box.top + 12; y < box.bottom - 12 && nodes.length < 6; y += 36) {
      const text = document.elementFromPoint(x, y)?.closest('.aui-md > *, [data-slot="aui_user-message-text"]')

      if (text && viewport.contains(text) && !nodes.some(([node]) => node === text)) {
        nodes.push([text, text.getBoundingClientRect().top])
      }
    }

    if (nodes.length) {
      holds.push({ viewport, nodes })
    }
  }

  return () => {
    for (const { viewport, nodes } of holds) {
      for (const [node, top] of nodes) {
        if (!node.isConnected || !node.checkVisibility() || !node.getClientRects().length) {
          continue
        }

        const delta = node.getBoundingClientRect().top - top

        if (Math.abs(delta) >= 0.5) {
          viewport.scrollTop += delta
        }

        break
      }
    }
  }
}

const setToolsShown = on => setConfig({ tools: on ? 'shown' : 'hidden' })

function ToolCallsRow() {
  const current = useSyncExternalStore(subscribe, getConfig)

  return jsx(sdk.ToggleRow, {
    checked: toolsShown(current),
    description:
      'Off keeps a reply to its answer: tool rows, run summaries and thinking are hidden. Approvals and questions always show.',
    id: 'monograph-tool-calls',
    label: 'Show tool calls',
    onChange: setToolsShown
  })
}

// ── Model logos ──
function logoFor(provider, model) {
  const hay = `${provider || ''}/${model || ''}`.toLowerCase()

  return LOGOS.find(([, needles]) => needles.some(needle => hay.includes(needle)))?.[0] ?? null
}

// ── Approval mode chip (composer, beside "+") ──
// Hermes keeps this control in the status bar, which this layout does not
// show. Same RPCs as the status bar item: config.get / config.set on
// `approvals.mode`, scoped to the profile the gateway is routed to.
const APPROVAL_MODES = [
  { description: 'Ask before actions that require approval', id: 'manual', label: 'Manual' },
  { description: 'Assess actions automatically and ask when needed', id: 'smart', label: 'Smart' },
  { description: 'Run without approval prompts', id: 'off', label: 'Off' }
]

const approvalLabel = mode => APPROVAL_MODES.find(entry => entry.id === mode)?.label ?? ''

const scoped = (profile, params) => {
  const name = String(profile || '').trim()

  return name ? { ...params, profile: name } : params
}

const normalizeApproval = value => {
  const mode = String(value ?? '')
    .trim()
    .toLowerCase()

  return APPROVAL_MODES.some(entry => entry.id === mode) ? mode : 'manual'
}

const useAtom = atom =>
  useSyncExternalStore(
    listener => atom.listen(listener),
    () => atom.get()
  )

// One mode per profile, shared by every chip: Hermes keeps a message box (and
// with it a chip) in each open session tab, and all of them must show the
// same truth. A pick in one chip is seen by the others at once; a change made
// elsewhere is read back from the gateway (see approvalSync in register()).
// `profiles`: profile key to its approvalMode state (src/machines/). `wanted`:
// profile name to how many mounted chips show it, the profiles to re-read.
const approval = { listeners: new Set(), profiles: new Map(), wanted: new Map() }

const approvalKey = profile => String(profile || '').trim() || 'default'

// One event into a profile's machine; the chips hear of it when it changed.
const approvalStep = (key, event) => {
  const before = approval.profiles.get(key) ?? approvalMode.start()
  const after = approvalMode.step(before, event, 0)

  if (after !== before) {
    approval.profiles.set(key, after)
    approval.listeners.forEach(listener => listener())
  }

  return after
}

const approvalSubscribe = listener => {
  approval.listeners.add(listener)

  return () => approval.listeners.delete(listener)
}

// Each request takes the profile's next revision and hands it back with the
// answer: the machine drops an answer to anything but the newest.
function readApproval(profile) {
  const key = approvalKey(profile)
  const { revision } = approvalStep(key, { type: 'read' })

  return sdk.host
    .request('config.get', scoped(profile, { key: 'approvals.mode' }))
    .then(result => {
      approvalStep(key, { mode: normalizeApproval(result?.value), revision, type: 'answer' })
    })
    .catch(() => undefined)
}

function writeApproval(profile, next) {
  const key = approvalKey(profile)
  const { revision } = approvalStep(key, { mode: next, type: 'write' })

  return sdk.host
    .request('config.set', scoped(profile, { key: 'approvals.mode', value: next }))
    .then(result => {
      approvalStep(key, { mode: normalizeApproval(result?.value ?? next), revision, type: 'answer' })
    })
    .catch(() => {
      approvalStep(key, { revision, type: 'failed' })
    })
}

// Re-read every profile a chip is showing on window focus (another window,
// or another app, may have changed it), and when a session.info carries a
// mode that differs from ours (the gateway sends one to every live session
// after a config.set, e.g. a slash command). Hermes' own Settings page saves
// by REST and sends no event; its composers mount again when Settings closes,
// and every chip reads the mode when it mounts.
function approvalSync() {
  const readAll = () => {
    for (const profile of approval.wanted.keys()) {
      void readApproval(profile)
    }
  }

  // A config.set sends one session.info per live session: one read for the
  // burst. The gateway's answer decides; the event only says "look again".
  let soon = 0

  const onInfo = event => {
    const payload = event?.payload ?? event
    const said = typeof payload?.approval_mode === 'string' ? normalizeApproval(payload.approval_mode) : null

    if (said && [...approval.profiles.values()].some(state => state.mode !== null && state.mode !== said)) {
      window.clearTimeout(soon)
      soon = window.setTimeout(readAll, approvalMode.rereadMs.info)
    }
  }

  window.addEventListener('focus', readAll)

  // `/approvals <mode>` typed in a message box: the gateway writes the config
  // but sends session.info only to sessions with a live agent, often none (an
  // idle or new session). Read again once the command has had time to run.
  const later = []

  const onKey = event => {
    if (event.key !== 'Enter' || event.shiftKey || event.isComposing || !(event.target instanceof Element)) {
      return
    }

    const box = event.target.closest('[data-slot="composer-root"]')

    if (box && /^\/approvals\b/i.test((event.target.textContent ?? '').trim())) {
      later.push(...approvalMode.rereadMs.command.map(ms => window.setTimeout(readAll, ms)))
      later.splice(0, Math.max(0, later.length - 4))
    }
  }

  document.addEventListener('keydown', onKey, true)

  // window.__mgState().approvalMode: each profile key's state.
  const stopExpose = expose('approvalMode', () =>
    Object.fromEntries([...approval.profiles].map(([key, state]) => [key, { ...state }]))
  )

  let stopInfo = null

  try {
    stopInfo = sdk.host?.onEvent?.('session.info', onInfo) ?? null
  } catch {
    stopInfo = null
  }

  return () => {
    window.removeEventListener('focus', readAll)
    document.removeEventListener('keydown', onKey, true)
    window.clearTimeout(soon)
    later.forEach(timer => window.clearTimeout(timer))
    stopExpose()

    if (typeof stopInfo === 'function') {
      stopInfo()
    }
  }
}

function ApprovalChip() {
  const profile = useAtom(sdk.host.state.profile)
  const gateway = useAtom(sdk.host.state.gateway)
  const key = approvalKey(profile)
  const mode = useSyncExternalStore(approvalSubscribe, () => approval.profiles.get(key)?.mode ?? null)
  // A write in progress is the profile's: every chip of it shows the write.
  const pending = useSyncExternalStore(approvalSubscribe, () => (approval.profiles.get(key)?.pending ?? 0) > 0)

  // The socket opens after the composer mounts. While mounted, this chip's
  // profile is one approvalSync keeps fresh.
  useEffect(() => {
    if (gateway !== 'open') {
      return undefined
    }

    approval.wanted.set(profile, (approval.wanted.get(profile) ?? 0) + 1)
    void readApproval(profile)

    return () => {
      const left = (approval.wanted.get(profile) ?? 1) - 1

      left > 0 ? approval.wanted.set(profile, left) : approval.wanted.delete(profile)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gateway, profile])

  if (!mode) {
    return null
  }

  const write = next => {
    void writeApproval(profile, next)
  }

  const title = `Approval mode: ${approvalLabel(mode)}`

  return jsxs(sdk.DropdownMenu, {
    onOpenChange: open => {
      if (open) {
        void readApproval(profile)
      }
    },
    children: [
      jsx(sdk.DropdownMenuTrigger, {
        asChild: true,
        children: jsxs('button', {
          'aria-label': title,
          className: 'mg-chip',
          'data-mg-approval': mode,
          'data-pending': pending ? '' : undefined,
          title,
          type: 'button',
          children: [
            jsx('i', { 'aria-hidden': true, className: 'codicon codicon-shield' }),
            jsx('span', { children: approvalLabel(mode) })
          ]
        })
      }),
      jsxs(sdk.DropdownMenuContent, {
        align: 'start',
        className: 'mg-approval-menu',
        side: 'top',
        sideOffset: 8,
        children: APPROVAL_MODES.map(entry =>
          jsxs(
            sdk.DropdownMenuItem,
            {
              'aria-checked': entry.id === mode,
              className: 'mg-approval-row',
              onSelect: () => write(entry.id),
              children: [
                jsxs('span', {
                  children: [jsx('b', { children: entry.label }), jsx('small', { children: entry.description })]
                }),
                entry.id === mode ? jsx('i', { 'aria-hidden': true, className: 'codicon codicon-check' }) : null
              ]
            },
            entry.id
          )
        )
      })
    ]
  })
}

// ── Effort slider: drag ──
// 41-effort.css draws Hermes' effort menu as a slider. Clicking a stop is
// Hermes' own handler; this only lets you drag across them by clicking the
// level under the pointer.
// The levels of the open effort menu: a radio group in a menu, while the
// effort pill says its menu is open (checked on the press, not with a
// document-wide :has()).
const EFFORT_GROUP = '[data-slot="dropdown-menu-content"] > [data-slot="dropdown-menu-radio-group"]'
const EFFORT_OPEN = '[data-testid="reasoning-pill"][aria-expanded="true"]'

// ── Surfaces: one button, top right, that opens any panel or page ──
// [key, label, codicon, letter, app action, default shortcut]. `null` is a rule.
const SURFACES = [
  ['browser', 'Browser', 'globe', 'b', 'view.showBrowser', 'mod+shift+l'],
  ['terminal', 'Terminal', 'terminal', 't', 'view.showTerminal', 'ctrl+`'],
  ['files', 'Files', 'files', 'f', 'view.showFiles', null],
  ['diff', 'Diff', 'diff', 'd', 'view.toggleReview', 'mod+g'],
  null,
  ['agents', 'Agents', 'hubot', 'a', 'nav.agents', null],
  ['artifacts', 'Artifacts', 'package', 'r', 'nav.artifacts', null],
  ['cron', 'Scheduled jobs', 'clock', 'j', 'nav.cron', null],
  ['messaging', 'Messaging', 'comment-discussion', 'm', 'nav.messaging', null],
  ['capabilities', 'Capabilities', 'extensions', 'c', 'nav.capabilities', null],
  ['settings', 'Settings', 'settings-gear', 's', 'nav.settings', 'mod+,']
]

const KEY_NAMES = {
  backspace: 'Backspace', delete: 'Delete', down: 'ArrowDown', enter: 'Enter', escape: 'Escape', left: 'ArrowLeft',
  pagedown: 'PageDown', pageup: 'PageUp', right: 'ArrowRight', space: ' ', tab: 'Tab', up: 'ArrowUp'
}

const KEY_CODES = {
  "'": 'Quote', ',': 'Comma', '-': 'Minus', '.': 'Period', '/': 'Slash', ';': 'Semicolon', '=': 'Equal',
  '[': 'BracketLeft', '\\': 'Backslash', ']': 'BracketRight', '`': 'Backquote'
}

let surfaceHost = null
let openSurfaces = null

// The shortcut an action answers to right now: the user's rebind if there is
// one (an empty list means they unbound it), else the shipped default.
function shortcutFor(action, fallback) {
  try {
    const stored = JSON.parse(window.localStorage.getItem('hermes.desktop.keybinds') || '{}')

    if (Array.isArray(stored?.[action])) {
      return typeof stored[action][0] === 'string' ? stored[action][0] : null
    }
  } catch {
    // Unreadable storage: Hermes falls back to its defaults too.
  }

  return fallback
}

// Hermes opens the terminal only from its own shortcut handler (plugins get no
// door to it), so press the shortcut for it.
function pressShortcut(combo) {
  const parts = combo.split('+')
  const base = parts.pop()
  const mac = /mac/i.test(navigator.platform)
  const mod = parts.includes('mod')

  window.dispatchEvent(
    new KeyboardEvent('keydown', {
      altKey: parts.includes('alt'),
      bubbles: true,
      cancelable: true,
      code: KEY_CODES[base] ?? (/^[a-z]$/.test(base) ? `Key${base.toUpperCase()}` : /^\d$/.test(base) ? `Digit${base}` : ''),
      ctrlKey: parts.includes('ctrl') || (mod && !mac),
      key: KEY_NAMES[base] ?? base,
      metaKey: mod && mac,
      shiftKey: parts.includes('shift')
    })
  )
}

function surfaceRows() {
  const allowed = new Set((surfaceHost?.listActions?.() ?? []).map(action => action.id))

  const hermes = SURFACES.map(row => {
    if (!row) {
      return null
    }

    const [key, label, icon, letter, action, fallback] = row
    const direct = allowed.has(action)
    const combo = direct ? null : shortcutFor(action, fallback)

    return { action, combo, direct, icon, key, label, letter, ready: direct || Boolean(combo) }
  })

  // Surfaces of Monograph's own modules come first, above a rule. A module
  // adds { key, label, icon, letter, run } to SHARED.surfaces.
  const own = (SHARED.surfaces ?? [])
    .filter(row => row && typeof row.run === 'function' && !hermes.some(other => other?.letter === row.letter))
    .map(row => ({ ...row, ready: true }))

  return own.length ? [...own, null, ...hermes] : hermes
}

// Is one of Hermes' panes on screen? (host.paneVisibility, where the host has it.)
const paneShown = id => {
  try {
    return Boolean(sdk.host?.paneVisibility?.(id)?.get?.())
  } catch {
    return false
  }
}

function showSurface(row) {
  if (row.run) {
    row.run()
  } else if (row.key === 'files' && paneShown('files') && surfaceHost?.listActions?.().some(action => action.id === 'view.toggleRightSidebar')) {
    // Files has no close control of its own (10-shell.css hides the
    // titlebar's right-sidebar toggle), so its row closes it again, as the
    // Diff row does for Diff. ⌘J is the same action.
    surfaceHost.runAction('view.toggleRightSidebar')
  } else if (row.direct) {
    surfaceHost.runAction(row.action)
  } else if (row.combo) {
    pressShortcut(row.combo)
  }
}

// Rendered as the titlebar button's glyph: Hermes owns the button (placement,
// tooltip, focus ring), this owns the menu that hangs from it.
function SurfacesGlyph() {
  const [open, setOpen] = useState(false)
  const hit = React.useRef(null)
  // How the menu is closing: a row was picked (its surface takes the focus),
  // or a press landed outside (focus stays where it went). Anything else
  // (Escape, the button again) hands focus back to the button, as Radix does
  // for a trigger that can hold focus; this trigger is a span inside Hermes'
  // button, so the button is focused by hand.
  const closing = React.useRef(null)

  useEffect(() => {
    openSurfaces = setOpen

    return () => {
      if (openSurfaces === setOpen) {
        openSurfaces = null
      }
    }
  }, [])

  const rows = open ? surfaceRows() : []

  const pick = row => {
    closing.current = 'picked'
    setOpen(false)
    // After the menu is gone, so the surface keeps the focus it takes.
    window.setTimeout(() => showSurface(row), 0)
  }

  return jsxs(sdk.DropdownMenu, {
    onOpenChange: next => {
      if (next) {
        closing.current = null
      }

      setOpen(next)
    },
    open,
    children: [
      jsx(sdk.DropdownMenuTrigger, {
        asChild: true,
        children: jsx('span', {
          className: 'mg-surfaces-hit',
          ref: hit,
          children: jsx('i', { 'aria-hidden': true, className: 'codicon codicon-layout-sidebar-right' })
        })
      }),
      jsxs(sdk.DropdownMenuContent, {
        align: 'end',
        className: 'mg-surfaces-menu',
        onCloseAutoFocus: event => {
          event.preventDefault()

          if (!closing.current) {
            hit.current?.closest('button')?.focus({ preventScroll: true })
          }

          closing.current = null
        },
        onInteractOutside: () => {
          closing.current = closing.current ?? 'outside'
        },
        // A bare letter opens its surface, as the keycaps say.
        onKeyDown: event => {
          if (event.metaKey || event.ctrlKey || event.altKey || event.key.length !== 1) {
            return
          }

          const row = rows.find(item => item?.ready && item.letter === event.key.toLowerCase())

          if (row) {
            event.preventDefault()
            event.stopPropagation()
            pick(row)
          }
        },
        sideOffset: 8,
        children: [
          jsx('div', { className: 'mg-surfaces-title', children: 'Open a surface' }, 'title'),
          ...rows.map((row, index) =>
            row
              ? jsxs(
                  sdk.DropdownMenuItem,
                  {
                    className: 'mg-surface-row',
                    disabled: !row.ready,
                    onSelect: () => pick(row),
                    children: [
                      jsx('i', { 'aria-hidden': true, className: `codicon codicon-${row.icon}` }),
                      jsx('span', { children: row.label }),
                      jsx('kbd', { children: row.letter.toUpperCase() })
                    ]
                  },
                  row.key
                )
              : jsx(sdk.DropdownMenuSeparator, {}, `rule-${index}`)
          )
        ]
      })
    ]
  })
}

function effortDrag() {
  let group = null

  const pick = event => {
    const levels = [...group.children]
    const box = group.getBoundingClientRect()
    const index = Math.min(levels.length - 1, Math.max(0, Math.floor(((event.clientX - box.left) / box.width) * levels.length)))
    const level = levels[index]

    if (level && level.getAttribute('aria-checked') !== 'true') {
      level.click()
    }
  }

  const down = event => {
    group = event.button === 0 ? event.target.closest?.(EFFORT_GROUP) : null

    if (group && !document.querySelector(EFFORT_OPEN)) {
      group = null
    }

    if (group) {
      pick(event)
    }
  }

  const move = event => {
    if (group && event.buttons & 1 && group.isConnected) {
      pick(event)
    }
  }

  const up = () => {
    group = null
  }

  document.addEventListener('pointerdown', down, true)
  document.addEventListener('pointermove', move, true)
  document.addEventListener('pointerup', up, true)
  document.addEventListener('pointercancel', up, true)

  return () => {
    document.removeEventListener('pointerdown', down, true)
    document.removeEventListener('pointermove', move, true)
    document.removeEventListener('pointerup', up, true)
    document.removeEventListener('pointercancel', up, true)
  }
}

const elapsedLabel = seconds => {
  const s = Math.max(1, Math.round(seconds))

  if (s < 60) {
    return `${s}s`
  }

  if (s < 3600) {
    return `${Math.floor(s / 60)}m ${s % 60}s`
  }

  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`
}

const ROW = '[data-slot="aui_assistant-message-root"]'
const RUNNING = '#mf-live, [data-slot="aui_turn-activity"], [data-slot="aui_response-loading"]'
const CONTENT = '[data-slot="aui_assistant-message-content"]'
const ROW_MARKS = ['mgSeg', 'mgPart', 'mgHead', 'mgWorked', 'mgSteps', 'mgOpen', 'mgAnim', 'role', 'tabindex', 'aria-expanded', 'aria-label']
const BUSY = '[data-slot="aui_turn-activity"], [data-slot="aui_response-loading"]'
const STORED_ID = /^(\d+\.\d+)-\d+-(?:user|assistant)$/
const STREAM_ID = /^assistant-stream-/
// A row Hermes is streaming (named by nextStreamMessageId).
const STREAMED_ID = /^assistant-(?:stream|interim)-/
const STALE_MIN_TEXT = 80
// A streamed row and the stored row of the same reply start within this many ms.
const STALE_MATCH_MS = 2000
const USER_ROW = '[data-slot="aui_user-message-root"]'
const THREAD = '[data-slot="aui_thread-content"]'
const VIEWPORT = '[data-slot="aui_thread-viewport"]'
const PAIR = '[data-slot="aui_turn-pair"]'
const GROUP = '[data-slot="aui_response-group"]'
const NEEDS_READER = '[data-slot^="tool-approval"], input, textarea, [role="radio"], [role="checkbox"]'

// Work done per frame on a thread that has just been mounted (a long history
// is dressed from the bottom up, a slice per frame).
const FRAME_BUDGET_MS = 6

// Hermes' compaction notes arrive as user messages.
const COMPACTION = /^\[(?:CONTEXT COMPACTION|STILL IN PROGRESS|CONTEXT SUMMARY\]:|END OF PRIOR CONTEXT)/

const stamp = node => Date.parse(node?.dateTime ?? '')
const streamedAt = row => Number(row?.dataset.messageId?.match(/^assistant-stream-(\d{12,})-/)?.[1] ?? NaN)
const plural = (count, word) => `${count} ${word}${count === 1 ? '' : 's'}`

const put = (node, name, value) => {
  if (value === null) {
    if (name in node.dataset) {
      delete node.dataset[name]
    }
  } else if (node.dataset[name] !== value) {
    node.dataset[name] = value
  }
}

// A row mark: `mg…` names are data attributes (as `put`), anything else
// (role, tabindex, aria-*) a plain attribute.
const isData = name => name.startsWith('mg')

const markRow = (node, name, value) => {
  if (isData(name)) {
    put(node, name, value)
  } else if (value === null) {
    node.removeAttribute(name)
  } else if (node.getAttribute(name) !== value) {
    node.setAttribute(name, value)
  }
}

const rowMarkDiffers = (node, name, value) =>
  isData(name) ? (value === null ? name in node.dataset : node.dataset[name] !== value) : node.getAttribute(name) !== value

// How many tool calls one top-level tool block stands for. Hermes draws a
// run of calls as one block ("Ran 10 commands, used 3 tools") whose rows are
// only mounted while it is open, so the count is the larger of the rows in
// it and the numbers its summary names. A clause with no number names one
// thing ("Edited app.ts"); a clause that starts with a number is a tally of
// something else ("2 tool calls failed") and is skipped. A lone call or card
// is one.
const RUN_CLAUSE = /^\s*\p{L}+\s+(\d+)\s+\p{L}/u

const callsIn = block => {
  if (!block.matches('[data-tool-group]')) {
    return 1
  }

  const rows = block.querySelectorAll('[data-tool-row]').length
  const summary = block.querySelector('[data-tool-summary]')?.textContent ?? ''
  let named = 0

  for (const clause of summary.split(/,\s+/)) {
    if (!clause.trim() || /^\s*\d/.test(clause)) {
      continue
    }

    named += Number(RUN_CLAUSE.exec(clause)?.[1] ?? 1)
  }

  return Math.max(rows, named, 1)
}

// ── Our own cost, measured ──────────────────────────────────────────────────
// window.__mgPerf: per job, how often it ran and how long it took (ms). The
// rig reads it; it costs two clock reads per run.
// `self` leaves out the time spent in other timed jobs it called (the
// layout reads, which are mostly Hermes' own layout brought forward).
const PERF = {}
let inner = 0

const round = value => Math.round(value * 100) / 100

const timed = (name, fn) =>
  function (...args) {
    const began = performance.now()
    const outer = inner

    inner = 0

    try {
      return fn.apply(this, args)
    } finally {
      const spent = performance.now() - began
      const self = spent - inner
      const entry = (PERF[name] ??= { max: 0, ms: 0, runs: 0, selfMax: 0 })

      inner = outer + spent
      entry.runs += 1
      entry.ms = round(entry.ms + spent)
      entry.max = Math.max(entry.max, round(spent))
      entry.selfMax = Math.max(entry.selfMax, round(self))
    }
  }

// window.__mgTrace: when the rig sets window.__mgTraceOn, the last fold
// decisions (which turn, running or not, and why).
const trace = item => {
  if (window.__mgTraceOn) {
    const list = (window.__mgTrace ??= [])

    list.push({ at: Date.now(), ...item })

    if (list.length > 300) {
      list.splice(0, list.length - 300)
    }
  }
}

function publishPerf() {
  const reset = () => Object.keys(PERF).forEach(key => delete PERF[key])

  window.__mgPerf = PERF
  window.__mgPerfReset = reset

  return () => {
    if (window.__mgPerf === PERF) {
      delete window.__mgPerf
      delete window.__mgPerfReset
    }
  }
}

// ── State, in the open ──────────────────────────────────────────────────────
// window.__mgState(): what every state machine holds right now, by name, as
// plain data. window.__mgState.machines: each machine's states. An adapter
// offers its reader with expose(id, read) and takes it back with the function
// that returns. A reader runs only when somebody asks, so this costs nothing
// until then.
const STATE_READERS = new Map()

const expose = (id, read) => {
  STATE_READERS.set(id, read)

  return () => {
    if (STATE_READERS.get(id) === read) {
      STATE_READERS.delete(id)
    }
  }
}

function publishState() {
  const read = () => {
    const out = {}

    for (const [id, reader] of STATE_READERS) {
      try {
        out[id] = reader()
      } catch (error) {
        out[id] = { error: String(error?.message ?? error) }
      }
    }

    return out
  }

  read.machines = Object.fromEntries(Object.entries(MACHINES).map(([id, machine]) => [id, machine.states]))
  window.__mgState = read

  return () => {
    if (window.__mgState === read) {
      delete window.__mgState
    }
  }
}

// ── Chat threads ────────────────────────────────────────────────────────────
// Hermes mounts a thread wherever a chat is shown (the main pane, tiles), so
// one observer on the body finds them. It only looks at nodes being added
// outside the threads it already knows; everything inside a thread is
// watched by that thread's own observers.
const finder = { observer: null, subs: new Set(), threads: new Set() }

const threadFound = thread => {
  if (!finder.threads.has(thread)) {
    finder.threads.add(thread)
    finder.subs.forEach(sub => sub.found(thread))
  }
}

const threadLost = thread => {
  finder.threads.delete(thread)
  finder.subs.forEach(sub => sub.lost(thread))
}

const findThreads = timed('finder', records => {
  let removed = false

  for (const record of records) {
    removed ||= record.removedNodes.length > 0

    if (!record.addedNodes.length) {
      continue
    }

    let inside = false

    for (const thread of finder.threads) {
      if (thread.contains(record.target)) {
        inside = true
        break
      }
    }

    if (inside) {
      continue
    }

    for (const node of record.addedNodes) {
      if (node.nodeType !== 1) {
        continue
      }

      if (node.matches(THREAD)) {
        threadFound(node)
      } else if (node.firstElementChild) {
        node.querySelectorAll(THREAD).forEach(threadFound)
      }
    }
  }

  if (removed) {
    for (const thread of finder.threads) {
      if (!thread.isConnected) {
        threadLost(thread)
      }
    }
  }
})

// Calls sub.found(thread) for every thread there is and every one mounted
// later, sub.lost(thread) when one leaves the page.
function onThreads(sub) {
  finder.subs.add(sub)

  if (!finder.observer) {
    finder.observer = new MutationObserver(findThreads)
    finder.observer.observe(document.body, { childList: true, subtree: true })
  }

  document.querySelectorAll(THREAD).forEach(threadFound)
  finder.threads.forEach(thread => sub.found(thread))

  return () => {
    finder.subs.delete(sub)

    if (!finder.subs.size) {
      finder.observer?.disconnect()
      finder.observer = null
      finder.threads.clear()
    }
  }
}

// One MutationObserver per thread. `ignore(record)` drops records that are
// the caller's own writes, so it is not woken by itself.
function watchThreads({ found, changed, lost, ignore, attributes = ['data-message-id'] }) {
  const observers = new Map()

  const stop = onThreads({
    found: thread => {
      if (observers.has(thread)) {
        return
      }

      const observer = new MutationObserver(records => {
        const kept = ignore ? records.filter(record => !ignore(record)) : records

        if (kept.length) {
          changed(thread, kept)
        }
      })

      observer.observe(thread, { attributeFilter: attributes, attributes: true, childList: true, subtree: true })
      observers.set(thread, observer)
      found(thread)
    },
    lost: thread => {
      observers.get(thread)?.disconnect()
      observers.delete(thread)
      lost?.(thread)
    }
  })

  return () => {
    stop()
    observers.forEach(observer => observer.disconnect())
    observers.clear()
  }
}

// ── Which turn is running ───────────────────────────────────────────────────
// From Hermes' own state, not from what happens to be drawn: the DOM's
// running markers come and go (between tool calls, and for over a second when
// a queued prompt takes over). A thread belongs to the main session
// (`data-session-anchor="workspace"`) or to a tile (`session-tile:<stored id>`);
// `busyBySession` is keyed by runtime id, so tiles are matched through the
// stored id each `session.info` names. Each session's turn is a sessionBusy
// machine (src/machines/session-busy.js), keyed by runtime id.
function turnState(onChange) {
  const atoms = sdk.host?.state
  const runtimeOf = new Map() // stored id → runtime id
  const sessions = new Map() // runtime id → sessionBusy state
  const idle = sessionBusy.start()
  const unbind = []
  let timer = 0

  const advance = (runtime, event, now) => {
    const was = sessions.get(runtime) ?? idle
    const next = sessionBusy.step(was, event, now)

    if (next !== was) {
      sessions.set(runtime, next)
    }

    return [was, next]
  }

  // One timer, set for the soonest handover to run out, so a second
  // session's handover does not push back the first one's re-check. When it
  // fires every session is stepped and it is set for the next.
  const arm = now => {
    let soonest = Infinity

    for (const state of sessions.values()) {
      if (state.phase === 'handover' && state.wakeAt < soonest) {
        soonest = state.wakeAt
      }
    }

    window.clearTimeout(timer)
    timer = soonest < Infinity ? window.setTimeout(wake, Math.max(0, soonest - now)) : 0
  }

  const wake = () => {
    const now = Date.now()

    for (const runtime of sessions.keys()) {
      advance(runtime, { type: 'tick' }, now)
    }

    arm(now)
    onChange()
  }

  // busyBySession is computed from every session's state, so it fires (with
  // a new object) on every streamed delta: only a change in which sessions
  // are busy is news here. That was a full pass in every frame of a reply.
  const busyKey = () => {
    const all = atoms?.busyBySession?.get?.() ?? {}

    return Object.keys(all).filter(id => all[id]).sort().join(' ')
  }
  let busyWas = busyKey()

  if (typeof atoms?.busyBySession?.listen === 'function') {
    unbind.push(atoms.busyBySession.listen(() => {
      const now = busyKey()

      if (now !== busyWas) {
        busyWas = now
        onChange()
      }
    }))
  }

  if (typeof atoms?.activeSessionId?.listen === 'function') {
    unbind.push(atoms.activeSessionId.listen(() => onChange()))
  }

  const off = sdk.host?.onEvent?.('*', event => {
    const runtime = event?.session_id
    const payload = event?.payload

    if (!runtime) {
      return
    }

    const now = Date.now()

    if (event.type === 'session.info') {
      if (payload?.stored_session_id) {
        runtimeOf.set(payload.stored_session_id, runtime)
      }

      if (Array.isArray(payload?.pending)) {
        // Only prompts still waiting behind the running one count.
        const [was, next] = advance(runtime, { type: 'pending', items: payload.pending }, now)

        if (was.phase === 'handover' && next.phase === 'idle') {
          onChange()
        }
      }
    } else if (event.type === 'message.start') {
      advance(runtime, { type: 'start', admission: event.admission_id ?? payload?.admission_id ?? null }, now)
      onChange()
    } else if (event.type === 'message.complete') {
      const [was, next] = advance(runtime, { type: 'complete' }, now)

      // Prompts were waiting: a handover begins (or begins again).
      if (next !== was && next.phase === 'handover') {
        arm(now)
      }

      onChange()
    }
  })

  const unexpose = expose('sessionBusy', () => Object.fromEntries([...sessions].map(([runtime, state]) => [runtime, { ...state }])))

  const runtimeFor = thread => {
    const anchor = thread.closest('[data-session-anchor]')?.dataset.sessionAnchor ?? ''

    if (anchor === 'workspace') {
      return atoms?.activeSessionId?.get?.() ?? null
    }

    if (anchor.startsWith('session-tile:')) {
      return runtimeOf.get(anchor.slice('session-tile:'.length)) ?? null
    }

    return null
  }

  return {
    runtimeFor,
    // true / false when Hermes knows, null when this thread is not matched.
    busy: thread => {
      const runtime = runtimeFor(thread)

      if (!runtime || !atoms?.busyBySession?.get) {
        return null
      }

      return Boolean(atoms.busyBySession.get()?.[runtime]) || sessionBusy.handingOver(sessions.get(runtime) ?? idle, Date.now())
    },
    stop: () => {
      unbind.forEach(undo => undo())
      window.clearTimeout(timer)
      unexpose()

      if (typeof off === 'function') {
        off()
      }
    }
  }
}

// ── Holding the page still ──────────────────────────────────────────────────
// The thread's viewport has overflow-anchor: none, and Hermes' stick-to-bottom
// owns scrollTop while the reader is at the bottom. When something above the
// reader changes height and they are not at the bottom, the element they are
// looking at is measured before and after and the difference scrolled away,
// in the same frame, so nothing is painted in between.
const atBottom = timed('layoutReads', viewport => viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight <= 2)

const holdStill = timed('layoutReads', viewport => {
  const box = viewport.getBoundingClientRect()
  const x = box.left + box.width / 2
  let y = box.top + Math.min(box.height * 0.3, 240)
  let hit = document.elementFromPoint(x, y)

  // A prompt can stick to the top of the viewport; read below it.
  const sticky = hit?.closest(USER_ROW)

  if (sticky && viewport.contains(sticky)) {
    y = Math.min(box.bottom - 4, sticky.getBoundingClientRect().bottom + 8)
    hit = document.elementFromPoint(x, y)
  }

  if (!hit || !viewport.contains(hit)) {
    return null
  }

  const block = hit.closest(`.aui-md > *, [data-slot="tool-block"], ${ROW}, ${USER_ROW}, ${PAIR}`)
  const nodes = [block, block?.closest(ROW), block?.closest(PAIR)].filter((node, index, all) => node && all.indexOf(node) === index)

  return { nodes: nodes.map(node => [node, node.getBoundingClientRect().top]), viewport }
})

const restore = timed('layoutReads', hold => {
  for (const [node, top] of hold?.nodes ?? []) {
    if (!node.isConnected || !node.getClientRects().length) {
      continue
    }

    const delta = node.getBoundingClientRect().top - top

    if (Math.abs(delta) >= 0.5) {
      hold.viewport.scrollTop += delta
    }

    return delta
  }

  return 0
})

// ── Keeping the bottom ──────────────────────────────────────────────────────
// Hermes keeps a running turn at the bottom in the same frame, but once a
// turn is not running (a queued prompt's hand-over, the swap to stored rows,
// our line and fold landing after the end, a window resize) its
// stick-to-bottom follows a frame late, and after a resize or a long stream it
// can lose the lock and stay off the bottom. While the reader is at the
// bottom this keeps them there: a ResizeObserver on each thread and its
// viewport runs after layout and before paint, and scrolls the growth away
// in that same frame.
//
// The reader leaves the bottom by input (wheel up, an arrow, page or Home
// key, a press on the scrollbar), or by anything else moving the view up
// that is not a shrink being clamped. They are back at the bottom when a
// scroll ends there. Nothing is done while text is selected in the thread,
// while Hermes holds the view (an inline edit, a session switch), or for a
// moment after the "Worked for" line is pressed (the line must stay put).
//
// It does not also scroll from the MutationObserver when rows arrive: that
// reads the height before layout, which forced a layout of the whole thread
// inside our own run (16 to 25 ms on a long one). A sampler in
// requestAnimationFrame can still see a gap for that frame; the ResizeObserver
// has closed it before the frame is painted.
//
// What it decides is the `scroll` machine (src/machines/scroll.js, its table
// at the top): one state per viewport. This function measures, writes
// scrollTop and owns the timer; the nodes it measures (the anchor, the line
// read, the holds) stay here beside the state.
function keepBottom() {
  const views = new Map() // viewport → { state, anchor, reading, holds, observed, timers and frames }
  const observer = new ResizeObserver(entries => settle(entries))
  const KEYS = new Set(['ArrowUp', 'PageUp', 'Home'])
  const TIME = { type: 'time', lost: false }
  const LOST = { type: 'time', lost: true }
  const WAKE = { type: 'wake' }
  const FOUND = { type: 'picked', found: true }
  const MISSED = { type: 'picked', found: false }

  const gapOf = viewport => viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight

  const selecting = viewport => {
    const selection = document.getSelection()

    return Boolean(selection && !selection.isCollapsed && selection.rangeCount && viewport.contains(selection.getRangeAt(0).commonAncestorContainer))
  }

  const held = viewport => viewport.hasAttribute('data-editing') || Boolean(viewport.closest('[data-session-switching]'))

  // A pressed element held where it is on screen (anchor), for a moment:
  // whatever grows or shrinks around it, the view follows so it stays under
  // the pointer. Read after layout (here, and once a frame while it lasts).
  const keepAnchor = (viewport, view) => {
    const anchor = view.anchor

    if (view.state.phase !== 'anchored' || !anchor) {
      return false
    }

    view.state = scroll.step(view.state, anchor.node.isConnected ? TIME : LOST, performance.now())

    if (view.state.phase !== 'anchored') {
      view.anchor = null

      return false
    }

    const delta = anchor.node.getBoundingClientRect().top - anchor.top

    if (Math.abs(delta) >= 0.5) {
      viewport.scrollTop += delta
    }

    return true
  }

  // Away from the bottom: the line of text the reader is on, read once a
  // frame after they scroll. A resize, or anything above it growing or
  // shrinking that nobody put back, puts it back where it was.
  // Several blocks down the view, not one: the first may be in what folds
  // (thinking, work rows), and then the next one still drawn is what the
  // reader keeps looking at.
  const pickReading = viewport => {
    const box = viewport.getBoundingClientRect()
    const x = box.left + box.width / 2
    const nodes = []

    for (let y = box.top + 12; y < box.bottom - 12 && nodes.length < 6; y += 36) {
      // Reply prose and tool rows only: a prompt can stick to the top while all moves.
      const text = document.elementFromPoint(x, y)?.closest('.aui-md > *, [data-slot="tool-block"]')

      if (text && viewport.contains(text) && !text.closest(USER_ROW) && !nodes.some(([node]) => node === text)) {
        nodes.push([text, text.getBoundingClientRect().top])
      }
    }

    return nodes.length ? { nodes } : null
  }

  const keepReading = (viewport, view, now) => {
    const reading = view.reading

    if (!reading || !scroll.putsBack(view.state, now)) {
      return
    }

    const at = reading.nodes.findIndex(([node]) => node.isConnected && node.getClientRects().length && node.checkVisibility())

    if (at < 0) {
      return
    }

    // The ones before it are gone from view (folded): it is the anchor now.
    reading.nodes.splice(0, at)

    const [node, top] = reading.nodes[0]
    const delta = node.getBoundingClientRect().top - top

    if (Math.abs(delta) >= 0.5) {
      viewport.scrollTop += delta
      view.state = scroll.step(view.state, { type: 'putBack', top: viewport.scrollTop }, now)
    }
  }

  const settle = timed('keepBottom', entries => {
    const done = new Set()

    for (const entry of entries) {
      const viewport = entry.target.matches(VIEWPORT) ? entry.target : entry.target.closest(VIEWPORT)
      const view = viewport && views.get(viewport)

      if (!view || done.has(viewport)) {
        continue
      }

      done.add(viewport)

      if (!viewport.isConnected || viewport.clientHeight < 1) {
        continue
      }

      if (view.holds.length) {
        view.holds.splice(0).forEach(restore)
        view.state = scroll.step(view.state, { type: 'restored', top: viewport.scrollTop }, performance.now())
      }

      if (keepAnchor(viewport, view)) {
        view.state = scroll.step(view.state, { type: 'at', top: viewport.scrollTop, gap: gapOf(viewport) }, performance.now())

        continue
      }

      const now = performance.now()
      // Hermes placing the view (a session switch, an inline edit) is read
      // only once a quiet is over, as before: while quiet it changes nothing.
      const isHeld = now >= view.state.quietUntil && held(viewport)

      if (!isHeld) {
        keepReading(viewport, view, now)
      }

      const top = viewport.scrollTop
      const gap = gapOf(viewport)

      // A fold of ours shrinks the thread while the reply still grows below
      // it: in one frame the shrink is clamped and the growth opens a gap,
      // which reads the same as a scroll up (`shrink` in the table). Any gap,
      // even the one pixel a fold above can leave, is closed while pinned.
      view.state = scroll.step(view.state, { type: 'layout', top, gap, held: isHeld }, now)

      if (view.state.toBottom && !selecting(viewport)) {
        viewport.scrollTop = viewport.scrollHeight - viewport.clientHeight
      }

      view.state = scroll.step(view.state, { type: 'at', top: viewport.scrollTop, gap: gapOf(viewport) }, now)

      if (window.__mgTraceOn) {
        trace({ kb: true, gap: Math.round(gap), top: Math.round(top), after: Math.round(view.state.top), pinned: scroll.pinnedOf(view.state), height: viewport.scrollHeight })
      }
    }
  })

  const release = event => {
    const view = views.get(event.currentTarget)

    if (view) {
      // The reader's own scroll ends any hold (our own nudge is untrusted).
      view.state = scroll.step(view.state, { type: 'input', trusted: event.isTrusted }, performance.now())

      if (event.isTrusted) {
        view.anchor = null
      }
    }
  }

  const onWheel = event => {
    if (event.deltaY < 0) {
      release(event)
    }
  }

  const onKey = event => {
    const target = event.target

    if ((KEYS.has(event.key) || (event.key === ' ' && event.shiftKey)) && !(target instanceof HTMLElement && (target.isContentEditable || target.matches('input, textarea, select')))) {
      release(event)
    }
  }

  // A press on the viewport itself is on its scrollbar (or its empty edge).
  const onPointer = event => {
    if (event.target === event.currentTarget) {
      release(event)
    }
  }

  // Back at the bottom: the scroll that ends there. Read only while away.
  const onScroll = event => {
    const viewport = event.currentTarget
    const view = views.get(viewport)

    // The line read is picked once the scroll has come to rest (keepReading
    // ignores the first 200 ms after a scroll anyway): a pick is a hit test,
    // which brings the frame's layout forward, so one per scroll frame cost
    // 0.6 ms each, 60 to 70 ms per scroll gesture.
    // Our own put-backs (keepReading, a hold restored) are not the reader
    // scrolling: the line read stays, and so does the hold through a resize
    // that lasts several frames.
    if (!view) {
      return
    }

    const now = performance.now()
    const was = view.state

    view.state = scroll.step(was, { type: 'scroll', top: viewport.scrollTop }, now)

    if (view.state === was) {
      return
    }

    view.reading = null
    window.clearTimeout(view.readingTimer)
    view.readingTimer = view.state.wakeAt ? window.setTimeout(() => {
      view.state = scroll.step(view.state, WAKE, performance.now())
      view.readingFrame ||= window.requestAnimationFrame(() => {
        view.readingFrame = 0
        view.reading = scroll.picks(view.state) && viewport.isConnected ? pickReading(viewport) : null
        view.state = scroll.step(view.state, view.reading ? FOUND : MISSED, performance.now())
      })
    }, Math.round(view.state.wakeAt - now)) : 0

    if (scroll.looks(view.state, now) && !held(viewport)) {
      view.state = scroll.step(view.state, { type: 'seen', gap: gapOf(viewport), top: viewport.scrollTop }, now)
    }
  }

  const listeners = [
    ['wheel', onWheel],
    ['keydown', onKey],
    ['pointerdown', onPointer],
    ['scroll', onScroll]
  ]

  const drop = viewport => {
    const view = views.get(viewport)

    if (view) {
      view.observed.forEach(node => observer.unobserve(node))
      window.cancelAnimationFrame(view.holdFrame)
      window.cancelAnimationFrame(view.readingFrame)
      window.clearTimeout(view.readingTimer)
      listeners.forEach(([type, fn]) => viewport.removeEventListener(type, fn))
      views.delete(viewport)
    }
  }

  const stopThreads = onThreads({
    found: thread => {
      const viewport = thread.closest(VIEWPORT)

      if (!viewport) {
        return
      }

      let view = views.get(viewport)

      if (!view) {
        view = { anchor: null, holdFrame: 0, holds: [], observed: new Set([viewport]), reading: null, readingFrame: 0, readingTimer: 0, state: scroll.start() }
        views.set(viewport, view)
        observer.observe(viewport)
        listeners.forEach(([type, fn]) => viewport.addEventListener(type, fn, { passive: true }))
      }

      if (!view.observed.has(thread)) {
        view.observed.add(thread)
        observer.observe(thread)
      }
    },
    lost: () => {
      for (const viewport of [...views.keys()]) {
        if (!viewport.isConnected) {
          drop(viewport)
        }
      }
    }
  })

  // Each view's state as of now, and what pinned() answers for it.
  const unexpose = expose('scroll', () => [...views.values()].map(view => {
    const now = performance.now()
    const state = scroll.step(view.state, view.anchor?.node.isConnected === false ? LOST : TIME, now)

    return { ...state, now, pinned: scroll.pinned(state, now), holds: view.holds.length, lines: view.reading?.nodes.length ?? 0 }
  }))

  return {
    // Whether the reader is held at the bottom (null: not known yet).
    pinned: viewport => {
      const view = viewport && views.get(viewport)

      return view ? scroll.pinned(view.state, performance.now()) : null
    },
    // A fold of ours is shrinking the thread for `ms`: a clamped scroll is
    // not the reader leaving the bottom.
    shrinking: (viewport, ms) => {
      const view = viewport && views.get(viewport)

      if (view) {
        view.state = scroll.step(view.state, { type: 'shrink', ms }, performance.now())
      }
    },
    // Hold `node` where it is on screen for `ms` while what is around it
    // opens or folds: Hermes' stick-to-bottom is let go first (the wheel-up
    // it takes as the reader leaving the bottom), so it does not follow the
    // growth down. Returns `fix`, to call right after the change.
    anchor: (viewport, node, ms) => {
      const view = viewport && views.get(viewport)

      if (!view || !node) {
        return () => {}
      }

      viewport.dispatchEvent(new WheelEvent('wheel', { deltaY: -1, bubbles: false, cancelable: false }))
      view.state = scroll.step(view.state, { type: 'anchor', ms }, performance.now())
      view.anchor = { node, top: node.getBoundingClientRect().top }

      const follow = () => {
        if (keepAnchor(viewport, view)) {
          window.requestAnimationFrame(follow)
        }
      }

      window.requestAnimationFrame(follow)

      return () => keepAnchor(viewport, view)
    },
    // A hold taken before our marks were written (holdStill), put back once
    // the browser has laid the change out (this observer runs after layout,
    // before paint), not by forcing a layout of the whole thread at once.
    // A change that resized nothing is put back in the next frame.
    restoreAfterLayout: hold => {
      const view = hold && views.get(hold.viewport)

      if (!view) {
        restore(hold)

        return
      }

      view.holds.push(hold)
      view.holdFrame ||= window.requestAnimationFrame(() => {
        view.holdFrame = 0
        view.holds.splice(0).forEach(restore)
        view.state = scroll.step(view.state, { type: 'restored', top: hold.viewport.scrollTop }, performance.now())
      })
    },
    // Leave the view alone for `ms` (a press on the line opens work in place).
    quiet: (viewport, ms) => {
      const view = viewport && views.get(viewport)

      if (view) {
        view.state = scroll.step(view.state, { type: 'quiet', ms }, performance.now())
      }
    },
    stop: () => {
      unexpose()
      stopThreads()
      observer.disconnect()
      ;[...views.keys()].forEach(drop)
    }
  }
}

// ── Model menu rows: no effort chip ──
// Hermes tags a row with how it is set: Fast, Daybreak, and the effort level.
// The stylesheet hides those tags in the composer's model menu; this marks the
// ones that are not an effort level so they come back. Effort labels are
// Hermes' fixed short forms (lib/reasoning-effort.ts), the same in every
// language, and a clamped pick reads "Ultra→Max".
//
// Also: every composer's model pill is marked `data-mg-pill` (Hermes marks only
// the main one, and a tile's pill label is translated), and the effort
// slider's colour (--mg-model on :root) is taken from the pill beside the
// effort pill whose menu is open, so two tiles on different vendors each get
// their own.
const EFFORT_CHIP = /^(off|min|low|med|high|xhigh|max|ultra)(→\w+)?$/i
const NEUTRAL_MODEL = '#9a9a9e'

// "Model · Anthropic: claude-x" in any language → "anthropic/claude-x".
const pillHay = pill => {
  const label = `${pill.getAttribute('aria-label') ?? ''}`.replace(/^[^·]*·\s*/, '').replace(/\s*[:：]\s*/, '/')

  return `${label} ${pill.textContent ?? ''}`.toLowerCase()
}

const modelColour = pill => {
  const hay = pillHay(pill)

  return LOGOS.find(([, needles]) => needles.some(needle => hay.includes(needle)))?.[2] ?? NEUTRAL_MODEL
}

// The model pill is the button just before the effort pill in its row.
const pillBeside = effort => {
  for (let node = effort.previousElementSibling; node; node = node.previousElementSibling) {
    const button = node.matches('button') ? node : node.querySelector('button')

    if (button) {
      return button
    }
  }

  return null
}

function modelChips() {
  const root = document.documentElement
  const portals = new Map() // portal → its own observer
  let queued = 0

  const markPills = () => {
    for (const effort of document.querySelectorAll('[data-testid="reasoning-pill"]')) {
      const pill = pillBeside(effort)

      if (pill) {
        put(pill, 'mgPill', '')
      }
    }

    paint(document.querySelector('[data-testid="reasoning-pill"][aria-expanded="true"]'))
  }

  // --mg-model from the model pill beside an effort pill. The only colour
  // source since build.mjs stopped generating :root:has() rules for it.
  const paint = effort => {
    const pill = effort && pillBeside(effort)

    if (pill) {
      const colour = modelColour(pill)

      if (root.style.getPropertyValue('--mg-model') !== colour) {
        root.style.setProperty('--mg-model', colour)
      }
    }
  }

  // The press that opens an effort menu sets the colour before React draws
  // the menu, so its first frame already wears it (main composer, a session
  // tile, after a model switch alike). The frame-later pass above covers a
  // menu opened any other way.
  const press = event => {
    if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ' && event.key !== 'ArrowDown') {
      return
    }

    paint(event.target?.closest?.('[data-testid="reasoning-pill"]'))
  }

  document.addEventListener('pointerdown', press, true)
  document.addEventListener('keydown', press, true)

  const mark = timed('modelChips', () => {
    queued = 0
    markPills()

    for (const portal of portals.keys()) {
      for (const chip of portal.querySelectorAll('[data-slot="dropdown-menu-sub-trigger"] > [data-slot="badge"]:not([data-mg-chip])')) {
        chip.dataset.mgChip = EFFORT_CHIP.test(chip.textContent.trim()) ? 'effort' : 'keep'
      }
    }
  })

  const schedule = () => {
    queued ||= window.requestAnimationFrame(mark)
  }

  // Menus are portals: direct children of the body. Each one is watched
  // while it is open (its rows load after it mounts), and let go when it
  // leaves. Nothing inside the rest of the page wakes this.
  const watch = portal => {
    if (portal.nodeType !== 1 || portal.id === 'root' || portals.has(portal) || /^(SCRIPT|STYLE|LINK)$/.test(portal.tagName)) {
      return
    }

    const observer = new MutationObserver(schedule)

    observer.observe(portal, { childList: true, subtree: true })
    portals.set(portal, observer)
  }

  const body = new MutationObserver(records => {
    for (const record of records) {
      record.addedNodes.forEach(watch)
      record.removedNodes.forEach(node => {
        portals.get(node)?.disconnect()
        portals.delete(node)
      })
    }

    schedule()
  })

  body.observe(document.body, { childList: true })
  ;[...document.body.children].forEach(watch)

  // Composers re-render (a session switch, a model change), so each chat
  // surface is watched; what happens inside its thread does not count.
  const surfaces = new Map() // surface → observer

  const stopThreads = onThreads({
    found: thread => {
      const surface = thread.closest('[data-chat-surface]')

      if (surface && !surfaces.has(surface)) {
        const observer = new MutationObserver(records => {
          if (records.some(record => !thread.contains(record.target))) {
            schedule()
          }
        })

        observer.observe(surface, { childList: true, subtree: true })
        surfaces.set(surface, observer)
      }

      schedule()
    },
    lost: () => {
      for (const [surface, observer] of surfaces) {
        if (!surface.isConnected) {
          observer.disconnect()
          surfaces.delete(surface)
        }
      }
    }
  })

  schedule()

  return () => {
    document.removeEventListener('pointerdown', press, true)
    document.removeEventListener('keydown', press, true)
    body.disconnect()
    stopThreads()
    surfaces.forEach(observer => observer.disconnect())
    surfaces.clear()
    portals.forEach(observer => observer.disconnect())
    portals.clear()
    window.cancelAnimationFrame(queued)
    root.style.removeProperty('--mg-model')
    document.querySelectorAll('[data-mg-pill]').forEach(node => put(node, 'mgPill', null))
  }
}

// Turn dressing. A reply is cut into segments: the rows between one prompt and
// the next (a queued prompt's bubble sits inside the reply). Once a segment is
// done its rows are marked, and 33-turns.css folds the work away under one
// line: how long it took, how many tool calls and messages are behind it.
// Attributes only on Hermes' nodes; the one element added is the copy button
// beside your own messages' hover time. A segment still running is never
// marked.
//
// Work is driven by the threads' own observers and by Hermes' turn state, one
// requestAnimationFrame at a time, and only for the turns that changed.
// ── Live reasoning in Simple mode ──
// Hermes' Simple mode rests reasoning collapsed (its policy
// reasoningCollapsedByDefault: "a quiet 'Thought for Ns' row"), so while a
// model thinks nothing of it shows: the owner's "thinking does not show".
// Opening a block by pressing its header made Hermes redraw the turn's parts
// (tool blocks replayed their entrance, the finished turn was not folded),
// so this sets the preference through the plugin SDK instead. In Simple
// mode Hermes routes that write to its session layer (in memory only,
// cleared when the mode changes, never the stored preference), and every
// block then streams as Hermes' own live preview from its first frame;
// turnDecor folds it to its header when the answer starts. In Advanced mode
// the setting is the reader's own preference and is left alone. A reader
// who sets it back in Simple mode is not overruled until the mode changes.
// With Monograph's thinking setting at "line" nothing is written (a write
// of ours is undone), and 33-turns.css keeps reasoning out of a running
// turn; it is still under the "Worked for" line afterwards.
const INTERFACE_MODE_KEY = 'hermes.desktop.interfaceMode.v1'
const REASONING_KEY = 'reasoning.collapsedByDefault'

function liveReasoning() {
  const settings = sdk.host?.settings

  if (typeof settings?.get !== 'function' || typeof settings.set !== 'function' || typeof settings.subscribe !== 'function') {
    return () => {}
  }

  const simple = () => {
    try {
      return window.localStorage.getItem(INTERFACE_MODE_KEY) === 'simple'
    } catch {
      return false
    }
  }

  let seen = simple()
  let mode = thinkingMode(getConfig())
  let lifted = false
  let timer = 0

  // Our write undone: only ours (lifted), only while it still stands.
  const drop = () => {
    if (lifted && simple() && settings.get(REASONING_KEY) === false) {
      settings.set(REASONING_KEY, true)
    }

    lifted = false
  }

  const check = (asked = false) => {
    timer = 0

    const now = simple()
    const changed = now !== seen || asked

    seen = now

    if (!now) {
      // Advanced: the setting is the reader's; a write of ours does not
      // reach it (Hermes cleared its session layer with the mode change).
      lifted = false

      return
    }

    try {
      if (mode === 'line') {
        drop()
      } else if (settings.get(REASONING_KEY) === true && (!lifted || changed)) {
        settings.set(REASONING_KEY, false)
        lifted = true
      }
    } catch (error) {
      console.warn('[monograph] live reasoning:', error)
    }
  }

  check()

  // Hermes clears its session layer when the mode changes; read the mode
  // after that has settled.
  const off = settings.subscribe(REASONING_KEY, () => {
    timer ||= window.setTimeout(check, 0)
  })

  // The Monograph setting, applied at once.
  const unsubscribe = subscribe(() => {
    const next = thinkingMode(getConfig())

    if (next !== mode) {
      mode = next
      window.clearTimeout(timer)
      check(true)
    }
  })

  return () => {
    off?.()
    unsubscribe()
    window.clearTimeout(timer)

    try {
      drop()
    } catch {}
  }
}

function turnDecor() {
  const folded = new Set()
  const prose = new WeakMap()
  // thread → { pairs: Set, queue: pairs still to dress after a mount, stale }
  const dirty = new Map()
  // pairs whose turn just ended while the reader is looking at them
  const deferred = new Set()
  const scrolling = new WeakSet()
  // pairs drawn as running, re-planned every pass until they settle
  const livePairs = new Set()
  // Thread or response group → its turn's run (machines/turn.js). The thread
  // also keeps when its last turn ended: Hermes swaps the streamed rows for
  // stored ones a moment after a turn ends; the new rows are that same turn.
  const turns = new WeakMap()
  const IDLE = turn.start()
  // One event, filled in before each step, so a pass allocates nothing.
  const READ = { type: 'read', running: false, runtime: null }
  const settledRows = new WeakMap() // pair → the ids of the reply rows it had when it settled
  const finishedRows = new WeakSet() // reply rows dressed as part of a finished turn
  // What is open (machines/disclosure.js): per work fold by head row, per
  // thinking block, per opened note by its first 200 characters (rows get
  // replaced). Missing is the start.
  const folds = new WeakMap()
  const thinks = new WeakMap()
  const noted = new Map()
  const START = disclosure.start()
  const PRESS = { type: 'press' }
  const LIVE = { type: 'read', live: true, rest: null }
  const REST = { type: 'read', live: false, rest: 'folded' }
  const GONE = { type: 'read', live: false, rest: null }
  // A note not open; made once, so a pass allocates nothing.
  const FOLDED = disclosure.step(START, REST)

  const disclose = (map, key, event) => {
    const was = map.get(key) ?? START
    const next = disclosure.step(was, event)

    if (next !== was) {
      map.set(key, next)
    }

    return next
  }

  let frame = 0
  let settleTimer = 0

  const unpublish = publishPerf()
  const bottom = keepBottom()

  const entryFor = thread => {
    let entry = dirty.get(thread)

    if (!entry) {
      entry = { pairs: new Set(), queue: null, stale: false }
      dirty.set(thread, entry)
    }

    return entry
  }

  const schedule = () => {
    frame ||= window.requestAnimationFrame(mark)
  }

  const strip = row => {
    for (const name of ROW_MARKS) {
      markRow(row, name, null)
    }

  }

  // The fold only moves when something just happened: a turn ended while the
  // reader was at the bottom, or the line was pressed. A thread opened from
  // history arrives folded.
  const animate = rows => {
    for (const row of rows) {
      row.dataset.mgAnim = ''
    }

    window.setTimeout(() => rows.forEach(row => put(row, 'mgAnim', null)), 520)
  }

  // Left-over live copies. After a switch to another session and back, Hermes
  // can keep the live copy of a turn in the thread beside the stored one: the
  // prompt is drawn twice and so is the reply. The live copy is marked and
  // 33-turns.css hides it. Two tests, both strict:
  //   a prompt is a copy when a later prompt in the thread carries the same
  //   timestamp (stored ids are "<timestamp>-<index>-user");
  //   a streamed reply row is a copy when its turn is not running and a
  //   stored row in the thread ends on the same text.
  const lastProse = row => {
    const blocks = row.querySelectorAll(`${CONTENT} > .aui-md`)

    return blocks.length ? blocks[blocks.length - 1].textContent.replace(/\s+/g, ' ').trim() : ''
  }

  const storedProse = row => {
    if (!prose.has(row)) {
      prose.set(row, lastProse(row))
    }

    return prose.get(row)
  }

  // `all` after a mount; otherwise only the last turns are read: copies sit
  // beside the turn they repeat, at the end of the thread, and a scroll that
  // mounts older turns must not cost a pass over every prompt in it.
  const markStale = timed('markStale', (thread, busy, all) => {
    const users = all ? [...thread.querySelectorAll(`${USER_ROW}:not([data-mg-queued])`)] : [...thread.querySelectorAll(PAIR)].slice(-6).flatMap(pair => [...pair.querySelectorAll(`${USER_ROW}:not([data-mg-queued])`)])
    const later = new Set()

    for (let index = users.length - 1; index >= 0; index -= 1) {
      const at = STORED_ID.exec(users[index].dataset.messageId ?? '')?.[1]

      // A live bubble (no stored id) is decided below, with its reply rows.
      if (at || !users[index].closest(PAIR)?.querySelector('[data-message-id^="assistant-stream-"]')) {
        put(users[index], 'mgStale', at && later.has(at) ? '' : null)
      }

      if (at) {
        later.add(at)
      }
    }

    const streamed = thread.querySelectorAll('[data-message-id^="assistant-stream-"]')

    if (!streamed.length) {
      return
    }

    // Copies sit beside the turn they repeat, at the end of the thread: only
    // the last few turns' stored rows are read, not the whole history.
    const recent = () => {
      const pairs = [...thread.querySelectorAll(PAIR)].slice(-4)

      return pairs.flatMap(pair => [...pair.querySelectorAll(ROW)]).filter(other => STORED_ID.test(other.dataset.messageId ?? ''))
    }

    let stored = null
    let storedTimes = null
    const copies = new Map() // pair → [rows that are copies, streamed rows]

    for (const row of streamed) {
      let copy = false
      const pair = row.closest(PAIR)

      if (!pair?.querySelector(BUSY) && !(busy && pair === lastPair(thread))) {
        // By time: a streamed row is named by the ms its first words arrived,
        // and the stored row of the same reply carries that moment in its id
        // (seconds). This holds when the original is far up the thread or
        // scrolled out, where its text is not rendered and the test below
        // finds nothing (youtube bot, 2026-11-17: the copy sat 7 turns down).
        const at = streamedAt(row)

        if (at) {
          storedTimes ??= [...thread.querySelectorAll('[data-message-id$="-assistant"]')]
            .map(other => STORED_ID.exec(other.dataset.messageId ?? '')?.[1])
            .filter(Boolean)
            .map(sec => Number(sec) * 1000)
          copy = storedTimes.some(ms => Math.abs(ms - at) <= STALE_MATCH_MS)
        }

        const text = copy ? '' : lastProse(row)

        if (!copy && text.length >= STALE_MIN_TEXT) {
          stored ??= new Set(recent().map(storedProse))
          copy = stored.has(text)
        }
      }

      put(row, 'mgStale', copy ? '' : null)

      if (pair) {
        const seen = copies.get(pair) ?? [0, 0]
        copies.set(pair, [seen[0] + (copy ? 1 : 0), seen[1] + 1])
      }
    }

    // The copy's own prompt: a live bubble (no stored id) in a turn whose
    // every reply row is a copy and that holds no stored row of its own.
    for (const [pair, [copied, total]] of copies) {
      const copy = copied > 0 && copied === total && ![...pair.querySelectorAll(ROW)].some(row => STORED_ID.test(row.dataset.messageId ?? ''))

      for (const user of pair.querySelectorAll(`${USER_ROW}:not([data-mg-queued])`)) {
        if (!STORED_ID.test(user.dataset.messageId ?? '')) {
          put(user, 'mgStale', copy ? '' : null)
        }
      }
    }
  })

  const lastPair = thread => {
    for (let child = thread.lastElementChild; child; child = child.previousElementSibling) {
      const pair = child.matches(PAIR) ? child : child.querySelector(PAIR)

      if (pair) {
        return pair
      }
    }

    return null
  }

  // A row's marks taken off: a work fold there is forgotten with them.
  const unmark = (row, writes) => {
    ROW_MARKS.forEach(name => writes.push([row, name, null]))
    folds.delete(row)
  }

  // What a finished segment's rows should carry, as [node, name, value].
  const dress = (pair, segment, next, wasLive, writes, lines) => {
    const { rows } = segment
    const head = rows[0]
    const answer = rows[rows.length - 1]

    // With the turn's own prompt hidden as a left-over copy, nothing says when
    // these rows began: no duration rather than a wrong one.
    const prompt = segment.prompt ?? pair.querySelector('[data-role="user"]')
    const started = segment.prompt && Number.isFinite(streamedAt(head)) ? streamedAt(head) : prompt && 'mgStale' in prompt.dataset ? NaN : stamp(prompt?.querySelector('time'))
    let times = rows.flatMap(row => [...row.querySelectorAll('[data-slot="aui_msg-actions"] time')])

    // Hermes draws the time on the last row of a reply, which may be a hidden copy.
    if (!times.length && !next) {
      times = [...pair.querySelectorAll('[data-slot="aui_msg-actions"] time')]
    }

    const handover = streamedAt(next?.rows[0])
    const ended = Number.isFinite(handover) ? handover : stamp(times[times.length - 1])
    const worked = Number.isFinite(started) && Number.isFinite(ended) && ended > started ? elapsedLabel((ended - started) / 1000) : ''

    let calls = 0
    let notes = 0
    let thoughts = 0

    for (const row of rows) {
      for (const block of row.querySelectorAll(`${CONTENT} > [data-slot="tool-block"]`)) {
        calls += callsIn(block)
      }

      notes += row.querySelectorAll(`${CONTENT} > .aui-md`).length
      thoughts += row.querySelectorAll(`${CONTENT} > [data-slot="aui_thinking-disclosure"]`).length
    }

    if (answer.querySelector(`${CONTENT} > .aui-md`)) {
      notes -= 1
    }

    const parts = [calls && plural(calls, 'tool call'), notes && plural(notes, 'message')].filter(Boolean)
    const steps = parts.join(', ') || (thoughts ? 'reasoning' : null)
    const state = !steps ? 'plain' : disclose(folds, head, REST).phase === 'open' ? 'open' : 'closed'
    const key = head.dataset.messageId ?? ''
    const fresh = Boolean(steps && wasLive && !folded.has(key) && head.dataset.mgSeg !== state)

    folded.add(key)

    // The line is a disclosure: a keyboard stop with a role and its state.
    // Only while tool calls are shown; hidden, the line is a plain label.
    const pressable = row => row === head && steps && toolsShown(getConfig())

    // What folds, marked on the elements themselves (data-mg-work="closed|
    // open"), so the stylesheet needs no selector that tries every element
    // in the page: the work rows after the first, the first row's own
    // children when it is not the answer, and in the answer row whatever
    // comes before its last prose and every tool block and thought.
    const work = new Set()

    if (steps) {
      for (const row of rows) {
        if (row === answer) {
          const content = row.querySelector(CONTENT)
          const kids = content ? [...content.children] : []
          const lastProse = kids.findLastIndex(kid => kid.classList.contains('aui-md'))

          kids.forEach((kid, at) => {
            if (at < lastProse || kid.matches('[data-slot="tool-block"], [data-slot="aui_thinking-disclosure"]')) {
              work.add(kid)
            }
          })
        } else if (row === head) {
          for (const kid of row.children) {
            work.add(kid)
          }
        } else {
          work.add(row)
        }
      }
    }

    for (const row of rows) {
      workMarks(row, work, state, writes)
    }

    for (const row of rows) {
      finishedRows.add(row)
    }

    for (const row of rows) {
      const line = pressable(row)

      writes.push(
        [row, 'mgSeg', state],
        [row, 'mgPart', row === answer ? 'answer' : 'work'],
        [row, 'mgHead', row === head ? '' : null],
        [row, 'mgWorked', row === head ? worked : null],
        [row, 'mgSteps', row === head ? steps : null],
        [row, 'role', line ? 'button' : null],
        [row, 'tabindex', line ? '0' : null],
        [row, 'aria-expanded', line ? String(state === 'open') : null],
        [row, 'aria-label', line ? (worked ? `Worked for ${worked}, ${steps}` : `Work: ${steps}`) : null]
      )

      if (row !== head || !steps) {
        writes.push([row, 'mgOpen', null])
        folds.delete(row)
      }

      lines.push([row, row === head ? {} : null])
    }

    return fresh
  }

  // row → the elements in it (itself included) that carry data-mg-work
  const worked = new WeakMap()

  const workMarks = (row, work, state, writes) => {
    const before = worked.get(row)
    const now = new Set([row, ...row.children, ...(row.querySelector(CONTENT)?.children ?? [])].filter(node => work.has(node)))

    for (const node of before ?? []) {
      if (!now.has(node)) {
        writes.push([node, 'mgWork', null])
      }
    }

    for (const node of now) {
      writes.push([node, 'mgWork', state])
    }

    if (now.size) {
      worked.set(row, now)
    } else {
      worked.delete(row)
    }
  }

  // A row no longer dressed (its turn runs again, or it waits to fold).
  const unwork = (row, writes) => workMarks(row, new Set(), null, writes)

  // Rows that intersect the viewport.
  const inView = timed('layoutReads', (rows, viewport) => {
    const box = viewport.getBoundingClientRect()

    return rows.some(row => {
      const rect = row.getBoundingClientRect()

      return rect.bottom > box.top && rect.top < box.bottom && rect.height > 0
    })
  })

  // Thinking. While reasoning streams Hermes shows it open, as a preview (a
  // body capped at 10rem, class max-h-40), and keeps that preview open once
  // the answer starts. Here it folds to its header line when the reasoning
  // is done (no shimmer on the label), with a height change only while the
  // reader is at the bottom (keepBottom holds the bottom through it; away
  // from the bottom the fold is instant and holdStill keeps what is read in
  // place). A press or Enter on the header unfolds it, in full, and folds it
  // again; Hermes' own state is left as it is. A block that never was a
  // live preview (history, or one the reader toggled in Hermes' own way) is
  // Hermes' to draw.
  //   data-mg-think="live|folded|open" on [data-slot="aui_thinking-disclosure"]
  const THINK = '[data-slot="aui_thinking-disclosure"]'

  // In Simple mode Hermes keeps live reasoning collapsed; liveReasoning()
  // below lifts that for the session, so Hermes itself draws the preview
  // from the first frame and this folds it like any other.
  const thinking = (group, out) => {
    for (const box of group.querySelectorAll(`${CONTENT} > ${THINK}`)) {
      const body = box.querySelector(':scope > [data-slot="aui_thinking-body"]')
      const header = box.querySelector('button[aria-expanded]')
      const was = (thinks.get(box) ?? START).phase
      const pending = Boolean(box.querySelector('.shimmer'))
      const phase = disclose(thinks, box, pending ? LIVE : body?.classList.contains('max-h-40') ? REST : GONE).phase
      const next = phase === 'none' ? null : phase

      out.writes.push([box, 'mgThink', next])

      if (header && (next === 'folded' || next === 'open')) {
        out.writes.push([header, 'aria-expanded', String(next === 'open')])
      }

      if (next === 'folded' && was === 'live' && out.pinned) {
        out.animate.push(box)
      }
    }
  }

  // One turn pair: what its rows should carry now.
  const plan = (pair, thread, busy, now, out) => {
    const group = pair.querySelector(GROUP)

    // Compaction notes and the copy button live on the prompt.
    const user = pair.querySelector(`${USER_ROW}:not([data-mg-queued])`)

    if (user) {
      const text = user.querySelector('[data-slot="aui_user-message-text"]')?.textContent.trimStart() ?? ''

      out.writes.push([user, 'mgCompaction', COMPACTION.test(text) ? (disclosure.step(noted.get(text.slice(0, 200)) ?? FOLDED, REST).phase === 'open' ? 'open' : 'closed') : null])
    }

    for (const bar of pair.querySelectorAll('[data-slot="aui_user-bubble-actions"]')) {
      const host = bar.querySelector('time')?.parentElement

      if (host && !host.querySelector('.mg-ucopy')) {
        out.buttons.push(host)
      }
    }

    if (!group) {
      return
    }

    // A left-over copy can still carry a running mark; it does not count.
    const marked = [...pair.querySelectorAll(RUNNING)].some(node => !node.closest('[data-mg-stale]'))
    // A turn that has ended and been folded is not running again just
    // because the session is busy while it is still the last one (a new
    // prompt is sent, its pair not drawn yet): only a running mark or a new
    // row of its own makes it run. Otherwise its tool rows would unfold for
    // a frame on every send. The working line waits at its end meanwhile.
    // A new row of its own is a streamed one it did not have when it
    // settled: Hermes swapping the streamed rows for stored ones (in Advanced
    // mode often more of them, a moment after the next prompt is sent) is
    // the same turn, not a new one.
    const rowList = group.querySelectorAll(`:scope > ${ROW}`)
    const done = settledRows.get(pair)
    const asked = marked || (busy === true && pair === out.last)
    // Both: more rows than it settled with, and one of them streamed and new.
    const grown = done !== undefined && rowList.length > done.size && [...rowList].some(row => STREAMED_ID.test(row.dataset.messageId ?? '') && !done.has(row.dataset.messageId))
    const waitingNext = asked && done !== undefined && !grown
    const running = asked && !waitingNext

    out.lines.push([group, waitingNext ? { working: true } : null])
    // The last turn's state belongs to the thread, not to the row elements:
    // Hermes swaps the streamed rows for stored ones as a turn ends, often
    // before it has settled here, and the new rows are still that turn.
    // Keyed by the session too: a thread element can be reused for another
    // session, which must not inherit a running turn.
    const key = pair === out.last && out.runtime ? thread : group
    const was = turns.get(key) ?? IDLE

    READ.running = running
    READ.runtime = key === thread ? out.runtime : null

    const wasLive = turn.live(was, READ.runtime)
    const next = turn.step(was, READ, now)
    const settled = next.phase === 'idle'

    if (next !== was) {
      turns.set(key, next)
    }

    if (next.phase === 'settling') {
      out.recheck = true
    }

    // "run" while the reply streams, "settle" for the moment after it
    // (Hermes swaps in the stored rows then: they are the same reply, and
    // must not arrive again). Arrivals play under "run" only.
    out.writes.push([pair, 'mgLive', running ? 'run' : !settled ? 'settle' : null])

    if (running || !settled) {
      livePairs.add(pair)
    } else {
      livePairs.delete(pair)
    }

    if (running !== wasLive || (!running && !settled)) {
      trace({ busy, last: pair === out.last, marked, running, settled, turn: pair.querySelector(USER_ROW)?.dataset.messageId ?? '?' })
    }

    thinking(group, out)

    const segments = [{ prompt: null, rows: [] }]
    // The first streamed row after the rows a settled turn ended with begins
    // the next turn's segment, bubble or not: a prompt sent while the turn
    // was still busy is queued, and Hermes streams its first row before our
    // bubble for it lands (a frame later). Without this the finished rows
    // took the new row in, ran again and lost their fold for that frame.
    let wasDone = false

    for (const child of group.children) {
      if (child.matches('[data-mg-queued]')) {
        segments.push({ prompt: child, rows: [] })
        wasDone = false
      } else if (child.matches('[data-mg-stale]')) {
        unmark(child, out.writes)
        unwork(child, out.writes)
        out.lines.push([child, null])
      } else if (child.matches(ROW)) {
        const known = finishedRows.has(child)

        if (wasDone && !known) {
          segments.push({ prompt: null, rows: [] })
        }

        wasDone = known
        segments[segments.length - 1].rows.push(child)
      }
    }

    segments.forEach((segment, index) => {
      const last = index === segments.length - 1

      if (!segment.rows.length) {
        // A queued prompt handed over, its first words not yet streamed:
        // the working line goes right after its bubble (the first row will
        // take that same line over, so nothing is put in or taken out when
        // the first words arrive).
        if (segment.prompt) {
          out.lines.push([segment.prompt, last && running ? { working: true } : null])
        }

        return
      }

      if (segment.prompt) {
        out.lines.push([segment.prompt, null])
      }

      // A finished turn only waiting for the next prompt's rows is not
      // taken apart: it stays folded, its working line at the group's end.
      // Nor is one already dressed as finished that is only settling again
      // (Hermes' busy flag drops and comes back between a turn and the
      // prompt queued behind it): a fold mark is never absent for a frame.
      const refinished = !running && segment.rows.every(row => finishedRows.has(row))

      if (last && !settled && !waitingNext && !refinished) {
        // The working indicator: the line of the segment that runs (its
        // first row has the line's room), one per thread, only while it runs.
        segment.rows.forEach(row => unmark(row, out.writes))
        segment.rows.forEach(row => unwork(row, out.writes))
        // Once it stops running the same line stays, empty, until it is
        // dressed: a line of ours put into or taken out of the response
        // group on its own trips Hermes' `.prose :where(h2 + *)` rules,
        // which restyle the whole reply (5,300 elements for a 2,000-line
        // one) twice at every turn end. Kept, it only changes its marks, and
        // a line for rows Hermes swaps in goes in with them, in their frame.
        // The line draws nothing while it works: the status row under the
        // reply (Hermes' own, or a live-status line) says the turn is running.
        segment.rows.forEach((row, at) => out.lines.push([row, at === 0 ? (running ? { working: true } : {}) : null]))

        return
      }

      // Just ended under the reader's eyes, and they are not at the bottom:
      // wait until they scroll it out of view or back to the bottom.
      const waiting = deferred.has(pair)
      // Rows already folded are this turn's own, not ones swapped in from
      // history: they are never taken apart again to wait.
      const remounted =
        !wasLive && pair === out.last && turn.remounted(turns.get(thread) ?? IDLE, out.runtime, now) && !segment.rows.some(row => row.dataset.mgSeg)

      if (last && (wasLive || waiting || remounted) && !out.pinned && out.viewport && inView(segment.rows, out.viewport)) {
        deferred.add(pair)
        segment.rows.forEach(row => unmark(row, out.writes))
        segment.rows.forEach(row => unwork(row, out.writes))
        segment.rows.forEach(row => out.lines.push([row, null]))

        return
      }

      if (last) {
        deferred.delete(pair)
      }

      if (dress(pair, segment, segments[index + 1], wasLive || running || waiting, out.writes, out.lines) && out.pinned) {
        out.animate.push(...segment.rows)
      }
    })

    // Kept while it runs again (the split above needs it), replaced when it
    // settles again.
    if (settled) {
      settledRows.set(pair, new Set([...rowList].map((row, at) => row.dataset.messageId ?? `#${at}`)))
    }
  }

  // Marks that change how tall a row is.
  const SHAPE = new Set(['mgSeg', 'mgPart', 'mgHead', 'mgOpen', 'mgCompaction', 'mgStale', 'mgThink', 'mgWork'])

  // ── The line, as an element ──
  // "Worked for 7m 56s · 12 tool calls" (while the turn runs: its room,
  // held empty) is one small element of ours, <div class="mg-line">, put
  // in the response group right before the row whose room it fills (as the
  // queued bubbles are). It used to be a ::before on the row: any generated
  // box on a reply row (even content "" or a single letter, in or out of
  // flow) put the compositor commit of scrolling a 2,000-line reply at 700
  // to 2,500 ms against 15 to 35 ms bare; this element, the same pixels,
  // keeps it at bare's. The row still takes the press and the keyboard.
  const lineOf = new WeakMap() // row → its line
  const lines = new Set()

  const LINE_HTML = '<span class="mg-line-worked"></span><span class="mg-line-steps"></span><span class="mg-line-arrow">\ueab6</span>'

  const setText = (node, text) => {
    if (node.textContent !== text) {
      node.textContent = text
    }
  }

  // A line belongs to a reply row (it sits right before it) or, while a
  // handed-over queued prompt has no row yet, to that prompt's bubble (it
  // sits right after it).
  const ownerOf = new WeakMap() // line → its row or bubble
  const isBubble = node => 'mgQueued' in node.dataset
  const isGroup = node => node.matches(GROUP)
  const inPlace = (line, owner) =>
    isGroup(owner) ? line.parentElement === owner && !line.nextElementSibling : isBubble(owner) ? line.previousElementSibling === owner : line.nextElementSibling === owner

  const syncLine = (row, spec) => {
    let line = lineOf.get(row)

    if (!spec) {
      if (line) {
        line.remove()
        lines.delete(line)
        lineOf.delete(row)
      }

      return
    }

    // The first row after a bubble takes the bubble's working line over
    // where it stands: the same element, so the group gains and loses nothing.
    const before = line ? null : row.previousElementSibling

    const bubble = before && lines.has(before) && !isBubble(row) && !isGroup(row) ? ownerOf.get(before) : null

    if (bubble && 'mgWorking' in before.dataset && (isBubble(bubble) ? before.previousElementSibling === bubble : isGroup(bubble) && before.parentElement === bubble)) {
      line = before
      lineOf.delete(bubble)
      lineOf.set(row, line)
      ownerOf.set(line, row)
    }

    if (!line) {
      line = document.createElement('div')
      line.className = 'mg-line'
      line.setAttribute('aria-hidden', 'true')
      line.innerHTML = LINE_HTML
      lineOf.set(row, line)
      ownerOf.set(line, row)
      lines.add(line)
    }

    if (!inPlace(line, row)) {
      if (isGroup(row)) {
        row.appendChild(line)
      } else if (row.parentElement) {
        row.parentElement.insertBefore(line, isBubble(row) ? row.nextElementSibling : row)
      }
    }

    put(line, 'mgWorking', spec.working ? '' : null)

    if (isBubble(row) || isGroup(row)) {
      return
    }

    // The words fade in when they first appear on a line that just ended
    // (the line itself is already there: it was the working line).
    const silent = !line.children[0].textContent && !line.children[1].textContent

    words(row, line)

    if (silent && 'mgAnim' in row.dataset && !('mgAnim' in line.dataset) && (line.children[0].textContent || line.children[1].textContent)) {
      line.dataset.mgAnim = ''
      window.setTimeout(() => put(line, 'mgAnim', null), 520)
    }
  }

  // The words come from the row's own marks (data-mg-worked, data-mg-steps,
  // data-mg-open), so whatever sets those is what the line says.
  const words = (row, line) => {
    const working = 'mgWorking' in line.dataset
    const worked = working || !row.dataset.mgWorked ? '' : `Worked for ${row.dataset.mgWorked}`
    const named = working ? '' : row.dataset.mgSteps ?? ''
    const steps = named && worked ? `  ·  ${named}` : named

    setText(line.children[0], worked)
    setText(line.children[1], steps)
    put(line, 'mgSteps', steps ? '' : null)
    put(line, 'mgOpen', steps && 'mgOpen' in row.dataset ? '' : null)
  }

  // A line whose row went (Hermes swapped in stored rows) or moved.
  const refreshLine = row => {
    const line = lineOf.get(row)

    if (line) {
      words(row, line)
    }
  }

  const dropOrphanLines = () => {
    for (const line of lines) {
      const owner = ownerOf.get(line)

      if (!line.isConnected || !owner?.isConnected || lineOf.get(owner) !== line || !inPlace(line, owner)) {
        line.remove()
        lines.delete(line)
      }
    }
  }

  const mark = timed('turnDecor', () => {
    frame = 0

    const now = Date.now()
    const stopAt = performance.now() + FRAME_BUDGET_MS
    let recheck = false
    let more = false

    for (const [thread, entry] of [...dirty]) {
      dirty.delete(thread)

      if (!thread.isConnected) {
        continue
      }

      const viewport = thread.closest(VIEWPORT)
      const busy = state.busy(thread)
      let pinned
      const out = {
        runtime: state.runtimeFor(thread),
        animate: [],
        buttons: [],
        last: lastPair(thread),
        // Asked only when a fold is decided. Hermes' flag first; if it says
        // no, measure (it can lag the last scroll event by a render).
        // keepBottom's own verdict first: it follows the reader's input, while
        // Hermes' flag lets go when a fold of ours shrinks the thread, and a
        // measure taken while the reply grows can read a gap that keepBottom
        // closes before paint.
        get pinned() {
          pinned ??= viewport ? (bottom.pinned(viewport) ?? (viewport.dataset.following === 'true' || atBottom(viewport))) : true

          return pinned
        },
        lines: [],
        recheck: false,
        viewport,
        writes: []
      }

      if (entry.stale) {
        markStale(thread, busy, entry.stale === 'all')
      }

      // The running turn and any deferred fold first, then what changed,
      // then (after a mount) the rest from the bottom up, a slice per frame.
      const done = new Set()
      const run = pair => {
        if (!done.has(pair) && pair.isConnected) {
          done.add(pair)
          plan(pair, thread, busy, now, out)
        }
      }

      if (out.last) {
        run(out.last)
      }

      for (const pair of [...deferred, ...livePairs]) {
        if (!pair.isConnected) {
          deferred.delete(pair)
          livePairs.delete(pair)
        } else if (thread.contains(pair)) {
          run(pair)
        }
      }

      const changed = [...entry.pairs]
      let queue = entry.queue

      while (changed.length && performance.now() < stopAt) {
        run(changed.pop())
      }

      while (!changed.length && queue?.length && performance.now() < stopAt) {
        run(queue.pop())
      }

      if (changed.length || queue?.length) {
        const next = entryFor(thread)

        changed.forEach(pair => next.pairs.add(pair))
        next.queue = queue?.length ? queue : null
        more = true
      }

      // Write. If any of it changes a row's height and the reader is not at
      // the bottom, keep what they are reading where it is.
      const changes = out.writes.filter(([node, name, value]) => rowMarkDiffers(node, name, value))
      const shape = viewport && changes.some(([, name]) => SHAPE.has(name))
      const hold = shape && !out.pinned ? holdStill(viewport) : null

      if (shape && out.pinned) {
        bottom.shrinking(viewport, 900)
      }

      for (const [node, name, value] of changes) {
        markRow(node, name, value)
      }

      if (out.animate.length) {
        animate(out.animate)
      }

      for (const host of out.buttons) {
        const button = document.createElement('button')

        button.type = 'button'
        button.className = 'mg-ucopy'
        button.setAttribute('aria-label', 'Copy')
        host.appendChild(button)
      }

      for (const [row, spec] of out.lines) {
        syncLine(row, spec)
      }

      dropOrphanLines()

      if (hold) {
        bottom.restoreAfterLayout(hold)
      }

      recheck ||= out.recheck

      if (viewport && deferred.size && !scrolling.has(viewport)) {
        scrolling.add(viewport)
        viewport.addEventListener('scroll', onScroll, { passive: true })
        viewports.add(viewport)
      }
    }

    if (recheck) {
      window.clearTimeout(settleTimer)
      settleTimer = window.setTimeout(touchRunning, turn.SETTLE_MS)
    }

    if (more) {
      schedule()
    }
  })

  const viewports = new Set()

  // The last pair of every thread: where a turn runs.
  const touchRunning = () => {
    for (const thread of finder.threads) {
      entryFor(thread)
    }

    schedule()
  }

  const onScroll = event => {
    if (!deferred.size) {
      return
    }

    const thread = event.currentTarget.querySelector(THREAD)

    if (thread) {
      entryFor(thread)
      schedule()
    }
  }

  const state = turnState(touchRunning)

  const GROUPISH = `${THREAD}, [data-slot="aui_message-group"], ${PAIR}, ${GROUP}`

  // Inside a block of reply prose (the block itself only gains children).
  const inProse = node => {
    const element = node.nodeType === 1 ? node : node.parentElement

    return Boolean(element?.closest('.aui-md'))
  }

  const stopThreads = watchThreads({
    // A thread mounted (a session opened, or Hermes remounting the thread
    // with rows from history after a turn): dressed now, in the observer's
    // microtask, from the bottom up, so the rows on screen are never painted
    // undressed; what the frame budget leaves goes on in later frames.
    found: thread => {
      const entry = entryFor(thread)

      entry.stale = 'all'
      entry.queue = [...thread.querySelectorAll(PAIR)]
      window.cancelAnimationFrame(frame)
      frame = 0
      mark()
    },
    changed: (thread, records) => {
      // Words streaming into a reply's prose change nothing planned here
      // (rows, tool blocks, thinking and the running marks are all outside
      // it): about one run in every frame of a long reply, 70 ms of script
      // per 2,000-line reply, for writes that were all unchanged.
      if (records.every(record => record.type === 'childList' || record.type === 'characterData' ? inProse(record.target) : false)) {
        return
      }

      const entry = entryFor(thread)
      let structural = false

      for (const record of records) {
        const target = record.target.nodeType === 1 ? record.target : record.target.parentElement

        if (record.type === 'attributes' || target?.matches(GROUPISH)) {
          entry.stale ||= true
          structural = true
        }

        const pair = target?.closest(PAIR)

        if (pair) {
          entry.pairs.add(pair)
        } else {
          for (const node of record.addedNodes) {
            if (node.nodeType === 1) {
              if (node.matches(PAIR)) {
                entry.pairs.add(node)
              } else {
                node.querySelectorAll(PAIR).forEach(found => entry.pairs.add(found))
              }
            }
          }
        }
      }

      // Rows added or replaced (a turn starting, history swapped in after a
      // turn) are dressed now, in this microtask, before the frame is
      // painted: React often commits inside an animation frame, and a
      // requestAnimationFrame asked for there runs a frame late, which would
      // show the rows undressed for one frame. Text streaming into a row
      // waits for the next frame.
      if (structural) {
        window.cancelAnimationFrame(frame)
        frame = 0
        mark()
      } else {
        schedule()
      }

    },
    // A row's line follows its marks (whoever writes them, a press on the
    // line included); that alone is no reason to plan again.
    // The copy buttons and the lines are ours; adding one (or taking a line
    // away) must not wake this.
    ignore: record =>
      // the line's own words (written by syncLine)
      record.target.parentElement?.classList.contains('mg-line') ||
      record.target.classList?.contains('mg-line') ||
      (record.type === 'childList' &&
      (record.addedNodes.length > 0 || record.removedNodes.length > 0) &&
      [...record.addedNodes].every(node => node.nodeType === 1 && (node.classList.contains('mg-ucopy') || node.classList.contains('mg-line'))) &&
      [...record.removedNodes].every(node => node.nodeType === 1 && node.classList.contains('mg-line')))
  })

  // The divider line is a pseudo-element, so a press on it lands on the row
  // that carries it, within its first 28px. The same goes for a compaction
  // note's line.
  const onLine = (event, selector) => {
    const head = event.target

    return head instanceof HTMLElement && head.matches(selector) && event.clientY - head.getBoundingClientRect().top <= 28 ? head : null
  }

  const HEAD = `${ROW}[data-mg-head][data-mg-steps]`

  // Opening work under the line must not move the line. At the bottom,
  // Hermes would follow the growth down; step off the bottom by a pixel
  // first, so it lets go, then open.
  const toggle = head => {
    const rows = [head]

    for (let row = head.nextElementSibling; row?.matches(ROW); row = row.nextElementSibling) {
      rows.push(row)
    }

    animate(rows)
    put(head, 'mgOpen', disclose(folds, head, PRESS).phase === 'open' ? '' : null)

    const thread = head.closest(THREAD)

    if (thread) {
      entryFor(thread).pairs.add(head.closest(PAIR))
      window.cancelAnimationFrame(frame)
      frame = 0
      mark()
    }
  }

  const click = event => {
    const copy = event.target instanceof Element ? event.target.closest('.mg-ucopy') : null

    if (copy) {
      event.preventDefault()
      event.stopPropagation()

      const text = copy.closest(USER_ROW)?.querySelector('[data-slot="aui_user-message-text"]')?.innerText ?? ''

      navigator.clipboard?.writeText(text).then(() => {
        copy.dataset.done = ''
        window.setTimeout(() => delete copy.dataset.done, 1200)
      })

      return
    }

    const note = event.target instanceof Element ? event.target.closest('[data-mg-compaction]') : null

    if (note && (note.dataset.mgCompaction === 'closed' || onLine(event, '[data-mg-compaction]'))) {
      event.preventDefault()
      event.stopPropagation()
      const text = note.querySelector('[data-slot="aui_user-message-text"]')?.textContent.trimStart().slice(0, 200) ?? ''
      const next = disclosure.step(noted.get(text) ?? FOLDED, PRESS)
      const open = next.phase === 'open'

      note.dataset.mgCompaction = open ? 'open' : 'closed'

      if (open) {
        noted.set(text, next)
      } else {
        noted.delete(text)
      }

      return
    }

    const box = event.target instanceof Element ? event.target.closest(`${THINK}:is([data-mg-think="folded"], [data-mg-think="open"])`) : null
    const header = box?.querySelector('button[aria-expanded]')

    if (header?.contains(event.target)) {
      event.preventDefault()
      event.stopPropagation()
      unfold(box, header)

      return
    }

    press(onLine(event, HEAD))
  }

  // Open or fold one block of thinking from its header. Opening must not move
  // the header: at the bottom, step off it by a pixel first (as for the line).
  const unfold = (box, header) => {
    const { phase } = disclose(thinks, box, PRESS)

    if (phase !== 'open' && phase !== 'folded') {
      return
    }

    const apply = () => {
      animate([box])
      box.dataset.mgThink = phase
      header.setAttribute('aria-expanded', String(phase === 'open'))
    }
    const viewport = box.closest(VIEWPORT)
    // The header the reader pressed stays under the pointer.
    const fix = viewport ? bottom.anchor(viewport, header, 900) : () => {}

    apply()
    fix()
  }

  const press = head => {
    if (!head || document.documentElement.dataset.mgTools === 'hidden') {
      return
    }

    const viewport = head.closest(VIEWPORT)
    // The line the reader pressed stays under the pointer, open or folded.
    const fix = viewport ? bottom.anchor(viewport, lineOf.get(head) ?? head, 900) : () => {}

    toggle(head)
    fix()
  }

  // The line from the keyboard: Enter and Space on the focused row (not on
  // a button or link inside it).
  const key = event => {
    if ((event.key !== 'Enter' && event.key !== ' ') || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || event.repeat) {
      return
    }

    const head = event.target

    if (head instanceof HTMLElement && head.matches(`${HEAD}[role="button"]`)) {
      event.preventDefault()
      press(head)
    }
  }

  let hovered = null

  const move = event => {
    const group = onLine(event, HEAD)

    if (group !== hovered) {
      lineOf.get(hovered)?.classList.remove('mg-hover')
      lineOf.get(group)?.classList.add('mg-hover')
      hovered = group
    }
  }

  // The keyboard ring is drawn on the line, which is not focusable: the
  // row's :focus-visible is mirrored onto it (data-mg-focus).
  let focused = null

  const focus = () => {
    const row = document.activeElement
    const head = row instanceof HTMLElement && row.matches(HEAD) && row.matches(':focus-visible') ? row : null

    if (head !== focused) {
      const before = lineOf.get(focused)

      if (before) {
        put(before, 'mgFocus', null)
      }

      focused = head
    }

    const line = lineOf.get(head)

    if (line) {
      put(line, 'mgFocus', '')
    }
  }

  // Tool calls shown or hidden: the line becomes, or stops being, a
  // disclosure; every finished turn is planned again.
  let shownTools = toolsShown(getConfig())

  const unsubscribe = subscribe(() => {
    if (toolsShown(getConfig()) !== shownTools) {
      shownTools = !shownTools

      for (const thread of finder.threads) {
        entryFor(thread).queue = [...thread.querySelectorAll(PAIR)]
      }

      schedule()
    }
  })

  // An arrival plays once per element: when it ends, or is cut short (the
  // element hidden for a moment), the element is marked and the stylesheet
  // never starts it again, whatever restyles it later (a mark rewritten, a
  // fold, Hermes moving the row).
  const arrived = event => {
    if (event.animationName === 'mg-stream-in' && event.target instanceof HTMLElement && !('mgArrived' in event.target.dataset)) {
      event.target.dataset.mgArrived = ''
    }
  }

  const unexpose = expose('disclosure', () => ({
    work: [...document.querySelectorAll(HEAD)].map(row => ({ row: row.dataset.messageId ?? null, ...(folds.get(row) ?? START) })),
    thinking: [...document.querySelectorAll(`${THINK}[data-mg-think]`)].map(box => ({ ...(thinks.get(box) ?? START) })),
    notes: [...noted.values()].map(note => ({ ...note }))
  }))

  // Each thread's last turn, keyed as plan() keys it.
  const unexposeTurn = expose('turn', () =>
    [...finder.threads].map(thread => {
      const last = lastPair(thread)
      const session = state.runtimeFor(thread)
      const key = last && session ? thread : last?.querySelector(GROUP)
      const { ended, ...run } = (key && turns.get(key)) ?? IDLE

      return { session, turn: last?.querySelector(USER_ROW)?.dataset.messageId ?? null, key: key === thread ? 'thread' : key ? 'group' : null, ...run, ended: ended && { ...ended } }
    })
  )

  document.addEventListener('animationend', arrived, true)
  document.addEventListener('animationcancel', arrived, true)
  document.addEventListener('click', click, true)
  document.addEventListener('keydown', key)
  document.addEventListener('mousemove', move, { passive: true })
  document.addEventListener('focusin', focus)
  document.addEventListener('focusout', focus)

  return () => {
    stopThreads()
    state.stop()
    bottom.stop()
    unpublish()
    unexpose()
    unexposeTurn()
    window.cancelAnimationFrame(frame)
    window.clearTimeout(settleTimer)
    document.removeEventListener('animationend', arrived, true)
    document.removeEventListener('animationcancel', arrived, true)
    document.querySelectorAll('[data-mg-arrived]').forEach(node => put(node, 'mgArrived', null))
    document.removeEventListener('click', click, true)
    document.removeEventListener('keydown', key)
    unsubscribe()
    document.removeEventListener('mousemove', move)
    document.removeEventListener('focusin', focus)
    document.removeEventListener('focusout', focus)
    viewports.forEach(viewport => viewport.removeEventListener('scroll', onScroll))
    document.querySelectorAll('.mg-ucopy').forEach(node => node.remove())
    document.querySelectorAll('.mg-line').forEach(node => node.remove())
    lines.clear()

    document.querySelectorAll('[data-mg-seg]').forEach(strip)
    document.querySelectorAll('[data-mg-work]').forEach(node => put(node, 'mgWork', null))
    document.querySelectorAll('[data-mg-stale]').forEach(node => put(node, 'mgStale', null))
    document.querySelectorAll('[data-mg-live]').forEach(node => put(node, 'mgLive', null))
    document.querySelectorAll('[data-mg-compaction]').forEach(node => put(node, 'mgCompaction', null))
    document.querySelectorAll('[data-mg-think]').forEach(node => {
      if (node.dataset.mgThink === 'folded') {
        node.querySelector('button[aria-expanded]')?.setAttribute('aria-expanded', 'true')
      }

      put(node, 'mgThink', null)
    })
  }
}

// ── Queued prompts ──────────────────────────────────────────────────────────
// A prompt sent while a turn is running goes to the gateway's queue. Hermes
// draws no row for it when its turn starts: the reply just continues under
// the previous prompt, and the bubble only turns up after the session is
// reloaded from history. Until Hermes draws it, the plugin does: the gateway
// says which queued prompt a `message.start` belongs to, and the bubble goes
// in front of the first reply row streamed after that start.
//
// The bubble is a copy of Hermes' own, so it follows whatever Hermes ships.
// It is dropped as soon as Hermes shows a prompt of its own in that place.
const QUEUED_KEY = 'hermes.plugin.monograph.queued'
// The gateway hands every event to plugins before Hermes' own dispatch, and
// Hermes names a streamed row by the time its first words are applied
// (nextStreamMessageId, Date.now()), which is never before that turn's
// message.start reached us. The previous turn's rows can be applied up to
// that very moment (a short reply is flushed whole at its message.complete,
// the event just before), so any margin back in time hands them to this
// prompt: with 40 ms, five fast queued replies put prompt 4's reply under
// prompt 5 (stress s4, "Q4 cannot be read whole").
const QUEUED_SKEW_MS = 0

function queuedBubbles(ctx) {
  // Each prompt is a queued machine (src/machines/queued.js). The Map keeps
  // the order records were made in: bubbles are placed, and saved, in it.
  const prompts = new Map() // admission id → queued state
  const live = new Map() // session id → admission id of the running turn
  let recordCount = 0 // prompts with a record (recorded or placed)
  let drawn = 0 // bubbles of ours the last render left in the page
  let frame = 0

  const move = (id, event, now) => {
    const was = prompts.get(id) ?? queued.start()
    const next = queued.step(was, event, now)

    if (next !== was) {
      const held = queued.hasRecord(next)

      if (held !== queued.hasRecord(was)) {
        recordCount += held ? 1 : -1
      }

      if (held && !queued.hasRecord(was)) {
        prompts.delete(id)
      }

      if (held || next.listed) {
        prompts.set(id, next)
      } else {
        prompts.delete(id)
      }
    }

    return next
  }

  try {
    const stored = JSON.parse(window.sessionStorage.getItem(QUEUED_KEY) || '[]')

    for (const record of Array.isArray(stored) ? stored : []) {
      if (record && record.id && typeof record.text === 'string') {
        move(record.id, { type: 'loaded', record }, Date.now())
        move(record.id, { type: 'aged' }, Date.now())
      }
    }
  } catch {
    prompts.clear()
    recordCount = 0
  }

  // The shape an installed older copy reads, and writes: [{ id, session, stored, text, at }].
  const save = () => {
    const list = []

    for (const [id, state] of prompts) {
      if (queued.hasRecord(state)) {
        list.push({ id, session: state.session, stored: state.stored, text: state.text, at: state.at })
      }
    }

    try {
      window.sessionStorage.setItem(QUEUED_KEY, JSON.stringify(list.slice(-40)))
    } catch {
      // Storage full or off: the bubbles then last until the next reload.
    }
  }

  const ours = node => node instanceof HTMLElement && ('mgQueued' in node.dataset || node.classList.contains('mg-line'))

  const skipOurs = node => {
    while (node && ours(node)) {
      node = node.nextElementSibling
    }

    return node
  }

  const streamedAt = node => Number(/^assistant-stream-(\d{13})-/.exec(node.dataset.messageId || '')?.[1] ?? 0)

  const build = (id, record, thread) => {
    const source = [...thread.querySelectorAll(`${USER_ROW}:not([data-mg-queued])`)].at(-1)
    let node = source?.cloneNode(true)
    let text = node?.querySelector('[data-slot="aui_user-message-text"]')

    if (text) {
      // Keep the path down to the text and the row with the time; drop
      // attachments, todo lists and anything else that belonged to the source.
      for (let part = text; part !== node; part = part.parentElement) {
        for (const other of [...part.parentElement.children]) {
          if (other !== part && !other.querySelector('time')) {
            other.remove()
          }
        }
      }

      for (const part of node.querySelectorAll('[id], [style]')) {
        part.removeAttribute('id')
        part.removeAttribute('style')
      }

      for (const button of node.querySelectorAll('time ~ button:not(.mg-ucopy)')) {
        button.remove()
      }
    } else {
      node = document.createElement('div')
      node.dataset.slot = 'aui_user-message-root'
      node.dataset.role = 'user'

      const bubble = node.appendChild(document.createElement('div'))

      bubble.className = 'composer-human-message'
      text = bubble.appendChild(document.createElement('div'))
      text.dataset.slot = 'aui_user-message-text'
    }

    // The source's own marks are not the copy's.
    for (const name of ['mgStale', 'mgCompaction']) {
      delete node.dataset[name]
    }

    const time = node.querySelector('time')

    if (time) {
      const at = new Date(record.at)

      time.dateTime = at.toISOString()
      time.textContent = at.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
      time.removeAttribute('data-state')
    }

    text.replaceChildren(document.createTextNode(record.text))
    text.style.whiteSpace = 'pre-wrap'

    const bubble = node.querySelector('.composer-human-message')

    // The copy can't edit or rewind, so it must not say it can.
    bubble?.setAttribute('tabindex', '-1')
    bubble?.removeAttribute('aria-label')
    node.removeAttribute('data-message-id')
    node.dataset.mgQueued = id

    node.querySelector('.sticky-human-clamp')?.setAttribute('data-mg-clamp', '')

    // A long prompt folds to four lines like Hermes' own; a press opens it.
    // Hermes folds with the class and fades with the attribute.
    node.addEventListener('click', event => {
      const clamp = node.querySelector('[data-mg-clamp]')

      if (!clamp || !('mgLong' in node.dataset) || event.target.closest('.mg-ucopy')) {
        return
      }

      const folded = clamp.classList.toggle('sticky-human-clamp')

      if (folded) {
        clamp.dataset.clamped = 'true'
      } else {
        delete clamp.dataset.clamped
      }
    })

    return node
  }

  // Hermes measures its bubbles to decide which ones fold; the copy carries
  // the source's answer, so measure again once it is in the page.
  const fit = node => {
    const clamp = node.querySelector('[data-mg-clamp]')

    if (!clamp) {
      return
    }

    clamp.classList.add('sticky-human-clamp')

    if (clamp.scrollHeight > clamp.clientHeight + 1) {
      clamp.dataset.clamped = 'true'
      node.dataset.mgLong = ''
    } else {
      delete clamp.dataset.clamped
      delete node.dataset.mgLong
    }
  }

  // Where one record's bubble belongs in a thread, or why it has none.
  const place = (id, record, thread, alone) => {
    const rows = [...thread.querySelectorAll('[data-message-id^="assistant-stream-"]')]
    // A row's id carries the time its first word arrived; the turn's own rows
    // start after its message.start (give or take the same task). With
    // queued prompts the turns follow each other within a few hundred ms, so
    // a wider margin hands the previous turn's reply to this prompt.
    const first = rows.find(row => streamedAt(row) >= record.at - QUEUED_SKEW_MS)

    if (first) {
      let before = first.previousElementSibling

      while (before && ours(before)) {
        before = before.previousElementSibling
      }

      // First row of its group: Hermes drew the prompt itself. A line of ours
      // in front of the row stays with the row: the bubble goes before it.
      const line = first.previousElementSibling?.classList.contains('mg-line') ? first.previousElementSibling : null

      return before ? { parent: first.parentElement, before: line ?? first } : 'shown'
    }

    // Nothing streamed yet. Only safe to guess the spot while that very turn
    // is known to be running in the one thread on screen.
    if (!alone || live.get(record.session) !== id) {
      return null
    }

    const group = [...thread.querySelectorAll(PAIR)].at(-1)?.querySelector(GROUP)
    const last = group && [...group.children].filter(child => child.dataset.messageId).at(-1)

    return last ? { parent: group, before: skipOurs(last.nextElementSibling) } : null
  }

  // Runs in a requestAnimationFrame, so a bubble lands in the same frame as
  // the reply row it belongs to and nothing below it is seen to move.
  const render = timed('queuedBubbles', () => {
    frame = 0

    const kept = new Set()

    if (recordCount) {
      const threads = [...finder.threads].filter(thread => thread.isConnected)
      const state = sdk.host?.state
      const focused = [state?.focusedSessionId?.get?.(), state?.focusedStoredSessionId?.get?.()].filter(Boolean)
      let shownAny = false

      for (const [id, record] of prompts) {
        if (!queued.hasRecord(record)) {
          continue
        }

        let shown = false
        let placed = false

        for (const thread of focused.length && !focused.includes(record.session) && !focused.includes(record.stored) ? [] : threads) {
          const spot = place(id, record, thread, threads.length === 1)

          if (spot === 'shown') {
            shown = true
          }

          if (!spot || spot === 'shown') {
            continue
          }

          let node = spot.parent.querySelector(`:scope > [data-mg-queued="${id}"]`)
          const fresh = !node

          if (fresh) {
            node = build(id, record, thread)
          }

          const after = spot.before?.classList?.contains('mg-line') ? node.nextElementSibling : skipOurs(node.nextElementSibling)

          if (node.parentElement !== spot.parent || after !== spot.before) {
            spot.parent.insertBefore(node, spot.before)
          }

          if (fresh) {
            fit(node)
          }

          kept.add(node)
          placed = true
          break
        }

        move(id, { type: 'read', shown, placed })
        shownAny ||= shown
      }

      if (shownAny) {
        save()
      }
    }

    for (const node of document.querySelectorAll('[data-mg-queued]')) {
      if (!kept.has(node)) {
        node.remove()
      }
    }

    drawn = kept.size
  })

  const schedule = () => {
    if (!frame && (recordCount || drawn)) {
      frame = window.requestAnimationFrame(render)
    }
  }

  const stop = ctx.onEvent?.('*', event => {
    const payload = event?.payload

    if (event?.type === 'session.info' && Array.isArray(payload?.pending)) {
      for (const item of payload.pending) {
        if (!item?.admission_id || item.steering || typeof item.text !== 'string' || !item.text.trim()) {
          continue
        }

        // Every prompt is admitted through the queue, most of them into an
        // idle session. Only one listed while another turn of the session
        // runs will continue that turn's reply without a bubble of its own.
        const behind = live.has(event.session_id) && live.get(event.session_id) !== item.admission_id

        move(item.admission_id, { type: 'listed', text: item.text, stored: payload.stored_session_id, behind })
      }

      // The 200 listed last are kept.
      let listed = 0

      for (const state of prompts.values()) {
        listed += state.listed ? 1 : 0
      }

      for (const [id, state] of prompts) {
        if (listed <= 200) {
          break
        }

        if (state.listed) {
          move(id, { type: 'evicted' })
          listed -= 1
        }
      }

      return
    }

    if (event?.type === 'message.complete') {
      live.delete(event.session_id)

      return
    }

    if (event?.type !== 'message.start') {
      return
    }

    const id = event.admission_id ?? payload?.admission_id
    const was = id ? prompts.get(id) : null

    live.set(event.session_id, id ?? '')

    // Every turn is noted, queued or not: the gateway does not say which it
    // was once the turn starts. A prompt Hermes drew itself is found in the
    // thread (`place` answers 'shown') and its record goes.
    if (!was?.listed || queued.hasRecord(was)) {
      return
    }

    const now = Date.now()

    for (const key of [...prompts.keys()]) {
      move(key, { type: 'aged' }, now)
    }

    move(id, { type: 'started', session: event.session_id }, now)
    save()
    schedule()
  })

  // A reply row being added is answered in the same microtask, not the next
  // frame: React often commits inside an animation frame, and a frame asked
  // for there runs a frame late, so the row was painted once without its
  // bubble and then moved down under it (a layout shift while pinned).
  const addsRow = records =>
    records.some(record => [...record.addedNodes].some(node => node.nodeType === 1 && (node.matches(ROW) || Boolean(node.querySelector(ROW)))))

  // Our own bubbles going in or out must not wake this.
  const stopThreads = watchThreads({
    found: schedule,
    changed: (thread, changes) => {
      if (recordCount && addsRow(changes)) {
        window.cancelAnimationFrame(frame)
        render()
      } else {
        schedule()
      }
    },
    ignore: record =>
      record.type === 'childList' && [...record.addedNodes, ...record.removedNodes].every(node => node.nodeType === 1 && ('mgQueued' in node.dataset || node.classList.contains('mg-line')))
  })

  const unexpose = expose('queued', () => ({
    live: Object.fromEntries(live),
    prompts: Object.fromEntries([...prompts].map(([id, state]) => [id, { ...state }]))
  }))

  schedule()

  return () => {
    stopThreads()
    unexpose()
    window.cancelAnimationFrame(frame)

    if (typeof stop === 'function') {
      stop()
    }

    document.querySelectorAll('[data-mg-queued]').forEach(node => node.remove())
  }
}

// ── Feature modules ─────────────────────────────────────────────────────────
// build.mjs puts every file of src/modules/ here, in name order, each inside
// its own block so names cannot collide. A module sees everything above (sdk,
// React, jsx, getConfig / setConfig / subscribe, put, ROW and so on) and adds
// itself with:
//   MODULES.push({ id: 'name', start(ctx) { …; return () => { /* undo */ } } })
// `start` runs once per plugin load, after the stylesheet is in place. A
// module that throws is skipped and the rest of the plugin carries on.
//
// Modules cannot see each other's names. What one offers to the others goes on
// SHARED, set at the top level of its file (files run in name order, so a
// module named 00-… is there before the rest): SHARED.services = { … }.
// Read it defensively (SHARED.services?.forTool(name)): the offering module
// may be missing from a build.
const MODULES = []
const SHARED = { surfaces: [] }

/* __MG_MODULES__ */

export default {
  id: ID,
  name: 'Monograph',
  register(ctx) {
    const root = document.documentElement
    const head = document.head
    const owner = `${Date.now()}-${Math.random()}`

    let style = document.getElementById(STYLE_ID)

    if (!style) {
      style = document.createElement('style')
      style.id = STYLE_ID
    }

    style.dataset.owner = owner

    if (style.textContent !== CSS) {
      style.textContent = CSS
    }

    // Stay last in <head> so lazily loaded app styles cannot outrank ours.
    const pin = () => {
      if (head.lastElementChild !== style) {
        head.appendChild(style)
      }
    }

    pin()

    const observer = new MutationObserver(pin)
    observer.observe(head, { childList: true })

    storage = ctx.storage

    const stored = storage.get('config', null)

    saved = stored && typeof stored === 'object' ? stored : {}
    config = { ...DEFAULTS, ...saved }

    applyConfig(config)
    root.dataset.mgReady = VERSION

    // The look must survive a Hermes that lacks a slot, so every contribution
    // is optional and guarded.
    try {
      // Settings > Plugins > Monograph. (Appearance has an `appearance.extra`
      // slot, but the page always opens on a sub-page, where it never mounts.)
      if (sdk.ToggleRow) {
        ctx.registerSettingsPage?.({
          icon: 'color-mode',
          id: 'settings',
          // A module may take the page over (SHARED.settingsPage, a component);
          // ToolCallsRow stays in scope for it to place.
          render: () => jsx(SHARED.settingsPage ?? ToolCallsRow, {}),
          title: 'Monograph'
        })
      }

      if (sdk.PALETTE_AREA) {
        ctx.register({
          area: sdk.PALETTE_AREA,
          data: {
            detail: () => (toolsShown(config) ? 'on' : 'off'),
            detailVariant: 'state',
            id: 'monograph-toggle-tool-calls',
            keepOpen: true,
            keywords: ['monograph', 'tools', 'trace', 'thinking', 'answer only', 'on', 'off'],
            label: 'Toggle tool calls',
            run: () => setToolsShown(!toolsShown(config))
          },
          id: 'monograph-toggle-tool-calls'
        })
      }
    } catch (error) {
      console.warn('[monograph] settings contributions skipped:', error)
    }

    // Composer: logos in the model menu, the approval chip, slider drag.
    try {
      if (sdk.MODEL_MENU_ROW_AREA) {
        ctx.register({
          area: sdk.MODEL_MENU_ROW_AREA,
          data: {
            decorate: ({ model, provider }) => {
              const logo = logoFor(provider, model)

              return logo ? { icon: jsx('span', { className: 'mg-logo', 'data-logo': logo }) } : null
            }
          },
          id: 'monograph-model-logos'
        })
      }

      if (sdk.COMPOSER_AREAS?.leading && sdk.DropdownMenu && sdk.host?.request && sdk.host?.state?.profile) {
        ctx.register({
          area: sdk.COMPOSER_AREAS.leading,
          id: 'monograph-approval-mode',
          render: () => jsx(ApprovalChip, {})
        })
      }
    } catch (error) {
      console.warn('[monograph] composer contributions skipped:', error)
    }

    // Top right: the surfaces button. A titlebar TOOL, not a `titleBar.right`
    // slot: a filled slot tells Hermes a page owns the band, and it would drop
    // its own controls on plugin pages.
    try {
      if (sdk.DropdownMenu && sdk.DropdownMenuItem && sdk.DropdownMenuSeparator) {
        surfaceHost = ctx
        ctx.register({
          area: 'titleBar.tools.right',
          data: {
            icon: jsx(SurfacesGlyph, {}),
            id: 'monograph-surfaces',
            label: 'Open a surface',
            // The pointer goes to the glyph, which toggles the menu itself.
            // What arrives here is the keyboard (Enter / Space on the button);
            // clicks bubbling up from the menu's rows are not ours.
            onSelect: event => {
              if (event?.detail === 0 && event.currentTarget?.contains?.(event.target)) {
                openSurfaces?.(true)
              }
            },
            tour: 'mg-surfaces'
          },
          id: 'monograph-surfaces'
        })
      }
    } catch (error) {
      console.warn('[monograph] surfaces button skipped:', error)
    }

    // Corner row: where the native window buttons sit, in page pixels. The
    // zoom factor comes from Hermes' preload (webFrame, exact in the same
    // tick). outerWidth / innerWidth is only the fallback: during a resize
    // outerWidth still holds the old width for up to ~100 ms, so the
    // fallback measures again once the resizing has been still for 150 ms.
    const zoomApi = window.hermesDesktop?.zoom
    let lights = ''
    let settle = 0

    const zoomNow = () => {
      try {
        const factor = Number(zoomApi?.factor?.())

        if (Number.isFinite(factor) && factor > 0) {
          return factor
        }
      } catch {
        // An older preload: fall back below.
      }

      return window.innerWidth > 0 && window.outerWidth > 0 ? window.outerWidth / window.innerWidth : 1
    }

    const placeLights = () => {
      const zoom = zoomNow()
      const next = `${(82 / zoom).toFixed(2)}px ${(17 / zoom).toFixed(2)}px`

      // Written only when it changes: nothing restyles on a plain resize.
      if (next !== lights) {
        lights = next
        root.style.setProperty('--mg-lights-y', `${(17 / zoom).toFixed(2)}px`)
        root.style.setProperty('--mg-lights-x', `${(82 / zoom).toFixed(2)}px`)
      }
    }

    const onResize = () => {
      placeLights()

      if (typeof zoomApi?.factor !== 'function') {
        window.clearTimeout(settle)
        settle = window.setTimeout(placeLights, 150)
      }
    }

    placeLights()
    window.addEventListener('resize', onResize)

    let stopZoom = null

    try {
      stopZoom = zoomApi?.onChanged?.(() => placeLights()) ?? null
    } catch {
      stopZoom = null
    }

    // Swapping the sidebar's side moves the main zone under the corner, and
    // Hermes measures its titlebar zones again only on a resize or a route
    // change. Tell it, the way its own titlebar does on a route change. The
    // swap comes from a press (Swap sidebar sides, ⌘\, the palette), so the
    // side is read once per press, a frame later, from the sidebar's border.
    const sideNow = () => {
      const sidebar = document.querySelector('[data-tour="sessions-sidebar"]')

      return sidebar ? (sidebar.classList.contains('border-l') ? 'right' : 'left') : null
    }

    let side = sideNow()
    let sideFrame = 0

    const checkSide = () => {
      cancelAnimationFrame(sideFrame)
      sideFrame = requestAnimationFrame(() => {
        const now = sideNow()

        if (now && side && now !== side) {
          window.dispatchEvent(new CustomEvent('hermes:titlebar-chrome-changed'))
        }

        side = now ?? side
      })
    }

    window.addEventListener('pointerup', checkSide, true)
    window.addEventListener('keyup', checkSide, true)

    const stopState = publishState()
    const stopApproval = approvalSync()

    const stopEffortDrag = effortDrag()
    const stopTurnDecor = turnDecor()
    const stopLiveReasoning = liveReasoning()
    const stopModelChips = modelChips()
    const stopQueuedBubbles = queuedBubbles(ctx)

    const stopModules = MODULES.map(module => {
      try {
        const stop = module.start(ctx)

        return typeof stop === 'function' ? stop : null
      } catch (error) {
        console.warn(`[monograph] module "${module.id}" skipped:`, error)

        return null
      }
    })

    root.dataset.mgModules = MODULES.map(module => module.id).join(' ')

    ctx.onDispose(() => {
      for (const stop of stopModules) {
        try {
          stop?.()
        } catch (error) {
          console.warn('[monograph] module teardown failed:', error)
        }
      }

      delete root.dataset.mgModules
      stopEffortDrag()
      stopTurnDecor()
      stopLiveReasoning()
      stopModelChips()
      stopQueuedBubbles()
      window.removeEventListener('resize', onResize)
      window.clearTimeout(settle)

      if (typeof stopZoom === 'function') {
        stopZoom()
      }

      window.removeEventListener('pointerup', checkSide, true)
      window.removeEventListener('keyup', checkSide, true)
      cancelAnimationFrame(sideFrame)
      stopApproval()
      stopState()
      observer.disconnect()
      listeners.clear()

      // A hot reload registers the next instance right away and it takes the
      // stylesheet over. Only tear down if nobody claimed it (plugin disabled).
      window.setTimeout(() => {
        if (style.dataset.owner !== owner) {
          return
        }

        style.remove()
        delete root.dataset.mgReady
        delete root.dataset.mgTools
        delete root.dataset.mgThinking
        delete root.dataset.mgMotion
        delete root.dataset.mgDensity
        root.style.removeProperty('--mg-greeting')
        root.style.removeProperty('--mg-lights-x')
        root.style.removeProperty('--mg-lights-y')
      }, 600)
    })
  }
}
